INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l37','look after','',NULL,'/lʊk ˈæftər/','However well we look after ourselves, we age.','无论怎样善待自己,我们都会衰老。','She looks after the children.','她照看孩子们。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l37','run out of','',NULL,'/rʌn aʊt ʌv/','A wound watch runs out of energy.','上了发条的表会耗尽能量。','We ran out of time.','我们的时间用完了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l37','in favor of','',NULL,'/ɪn ˈfeɪvər ʌv/','The odds are in favor of dying between 65 and 80.','概率偏向于在65至80岁之间死去。','He argued in favor of the plan.','他赞成这个计划。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l37','die of','',NULL,'/daɪ ʌv/','Many of us will die of old age.','我们许多人会老死。','He died of a fever.','他死于高烧。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp1','choice','{"stem":"\"At twelve the human body is at ___ most vigorous.\"(‘最…’= at __ most + 形容词,填那个形容词性物主代词)","options":["their","it","its","it''s"],"answer_index":2,"stem_cn":"十二岁时人体最为强健。","explanation_cn":"‘最…’= at its most + 形容词;填形容词性物主代词 its。✓ at its most vigorous. ✗ it(主格/宾格)/ it''s(= it is)/ their(复数):此处用 its。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp1','choice','{"stem":"\"At this age the likelihood of death is ___.\"(‘最小’,little 的最高级)","options":["little","lesser","less","least"],"answer_index":3,"stem_cn":"在这个年纪,死亡的可能性最小。","explanation_cn":"‘最小’,little 的最高级是 least。✓ the likelihood of death is least. ✗ less(比较级)/ little(原级)/ lesser:最高级用 least。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp1','choice','{"stem":"\"Aging is one of the ___ unpleasant discoveries we make.\"(‘最…之一’,one of the + 最高级,填 unpleasant 前那个词)","options":["most","very","much","more"],"answer_index":0,"stem_cn":"衰老是我们所发现的最令人不快的事情之一。","explanation_cn":"‘最…之一’= one of the + 最高级;unpleasant 是多音节,最高级前加 most。✓ one of the most unpleasant discoveries. ✗ more(比较级)/ very / much:多音节最高级用 most。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp2','choice','{"stem":"\"At twelve the body has ___ to reach its full strength.\"(‘尚未…’= have __ to do,填那个表‘还没’的副词)","options":["ever","still","yet","already"],"answer_index":2,"stem_cn":"十二岁时,身体尚未长到最强壮。","explanation_cn":"‘尚未…’= have yet to do;填副词 yet。✓ has yet to reach its full strength. ✗ still / ever / already:此结构用 yet。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp2','choice','{"stem":"\"Science has ___ to find a way to stop aging.\"(‘尚未…’的固定说法 have __ to do,填那个副词)","options":["still","yet","ever","soon"],"answer_index":1,"stem_cn":"科学尚未找到阻止衰老的办法。","explanation_cn":"‘尚未…’= have yet to do;填 yet。✓ has yet to find a way. ✗ still / ever / soon:此结构用 yet。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp2','choice','{"stem":"\"The full cause of aging has yet ___ be discovered.\"(have yet + 不定式,填不定式符号)","options":["for","at","to","of"],"answer_index":2,"stem_cn":"衰老的全部成因尚待发现。","explanation_cn":"have yet + 不定式;填不定式符号 to。✓ has yet to be discovered. ✗ for / at / of:不定式用 to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp3','choice','{"stem":"\"The loss of vigor, ___ imperceptible at first, becomes steep.\"(‘虽然’,让步连词,插在两逗号间)","options":["because","since","unless","though"],"answer_index":3,"stem_cn":"活力的丧失,虽起初难以察觉,最终却变得陡峭。","explanation_cn":"‘虽然…’的让步连词 though,可插在两逗号之间。✓ the loss of vigor, though imperceptible at first, … ✗ because / unless / since:让步用 though。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp3','choice','{"stem":"\"___ lucky and robust, no one can live for ever.\"(‘虽然/尽管’,让步连词置于句首)","options":["Though","So","Unless","Because"],"answer_index":0,"stem_cn":"纵然幸运又强健,也没人能永生。","explanation_cn":"‘虽然/尽管’的让步连词,置于句首用 Though。✓ Though lucky and robust, no one can live for ever. ✗ Because / Unless / So:让步用 Though。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp3','choice','{"stem":"\"An old watch, ___ still a watch, is worn and unreliable.\"(‘虽然’,让步连词)","options":["unless","because","if","though"],"answer_index":3,"stem_cn":"一只旧表虽然仍是表,却已磨损、不可靠。","explanation_cn":"‘虽然’的让步连词 though。✓ an old watch, though still a watch, is worn. ✗ because / unless / if:让步用 though。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp4','choice','{"stem":"\"Most animals age too, if ___ the chance to live long enough.\"(if + 过去分词(省略),‘如果被给予’,填‘给’那个动词的过去分词)","options":["to give","given","gave","giving"],"answer_index":1,"stem_cn":"多数动物只要有机会活得够久,也会衰老。","explanation_cn":"if + 过去分词(省略了主语和 be):if (they are) given → if given;填‘给’那个动词的过去分词 given。✓ if given the chance. ✗ giving(主动)/ gave / to give:省略结构用过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp4','choice','{"stem":"\"The body declines, if ___ to constant strain.\"(if + 过去分词(省略),被动‘如果被暴露于’,填‘使暴露/使接触’那个动词的过去分词)","options":["exposing","to expose","expose","exposed"],"answer_index":3,"stem_cn":"身体若长期受压,便会衰退。","explanation_cn":"if + 过去分词(省略),被动‘如果被暴露于’;填‘使暴露’那个动词的过去分词 exposed。✓ if exposed to constant strain. ✗ exposing(主动)/ expose / to expose:省略结构用过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp4','choice','{"stem":"\"The illness, if ___ early, can often be overcome.\"(if + 过去分词(省略),‘如果被治疗’,填‘治疗’那个动词的过去分词)","options":["treating","treated","treat","to treat"],"answer_index":1,"stem_cn":"那病若及早治疗,往往可以战胜。","explanation_cn":"if + 过去分词(省略),‘如果被治疗’;填‘治疗’那个动词的过去分词 treated。✓ if treated early. ✗ treating(主动)/ treat / to treat:省略结构用过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp5','choice','{"stem":"\"An old watch becomes so worn that it is not worth ___.\"(worth + 动名词,‘值得修’,填‘修理’那个动词的动名词)","options":["mend","mended","mending","to mend"],"answer_index":2,"stem_cn":"旧表磨损太甚,已不值得修理。","explanation_cn":"worth + 动名词,‘值得修’;填‘修理’那个动词的动名词 mending。✓ not worth mending. ✗ mended / mend / to mend:worth 后用动名词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp5','choice','{"stem":"\"The topic is well worth ___ in more detail.\"(worth + 动名词,‘值得研究’,填‘研究’那个动词的动名词)","options":["study","studied","to study","studying"],"answer_index":3,"stem_cn":"这个话题很值得更细致地探讨。","explanation_cn":"worth + 动名词,‘值得研究’;填‘研究’那个动词的动名词 studying。✓ well worth studying. ✗ studied / study / to study:worth 后用动名词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp5','choice','{"stem":"\"Good health is worth ___ at any age.\"(worth + 动名词,‘值得拥有’,填‘拥有’那个动词的动名词)","options":["have","had","having","to have"],"answer_index":2,"stem_cn":"健康在任何年纪都值得拥有。","explanation_cn":"worth + 动名词,‘值得拥有’;填‘拥有’那个动词的动名词 having。✓ health is worth having. ✗ had / have / to have:worth 后用动名词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp6','choice','{"stem":"\"The chance or probability of something happening is the ___.\"(“可能性”用哪个词)","options":["likelihood","childhood","neighborhood","brotherhood"],"answer_index":0,"stem_cn":"某事发生的机会或概率。","explanation_cn":"某事发生的机会或概率是 likelihood(可能性)。✓ the chance of something happening is the likelihood. ✗ neighborhood 街区;✗ childhood 童年;✗ brotherhood 手足情——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp6','choice','{"stem":"\"Easily hurt, harmed, or attacked means ___.\"(“脆弱的,易受伤的”用哪个词)","options":["veritable","valuable","vulnerable","variable"],"answer_index":2,"stem_cn":"容易受伤害或攻击的。","explanation_cn":"容易受伤害或攻击的是 vulnerable(脆弱的)。✓ easily hurt means vulnerable. ✗ valuable 有价值的;✗ variable 多变的;✗ veritable 真正的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',5,'am4_l37_gp6','choice','{"stem":"\"So small or gradual that it cannot be noticed is ___.\"(“察觉不到的,细微的”用哪个词)","options":["impossible","imperceptible","impatient","imperfect"],"answer_index":1,"stem_cn":"小或慢到无法察觉的。","explanation_cn":"小或慢到无法察觉的是 imperceptible(察觉不到的)。✓ too small to be noticed is imperceptible. ✗ impossible 不可能的;✗ impatient 不耐烦的;✗ imperfect 不完美的——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',6,NULL,'choice','{"stem":"likelihood 的意思是:","options":["必然性","可能性","重要性","偶然性"],"answer_index":1,"explanation_cn":"likelihood = 可能性。✓ the likelihood of death is least."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',6,NULL,'choice','{"stem":"vulnerable 的意思是:","options":["脆弱的,易受伤的","安全的","强壮的","独立的"],"answer_index":0,"explanation_cn":"vulnerable = 脆弱的、易受伤的。✓ we were far more vulnerable."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',6,NULL,'choice','{"stem":"imperceptible 的意思是:","options":["迅速的","巨大的","察觉不到的,细微的","明显的"],"answer_index":2,"explanation_cn":"imperceptible = 察觉不到的、细微的。✓ though imperceptible at first."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',6,NULL,'choice','{"stem":"robust 的意思是:","options":["苗条的","强健的,结实的","苍白的","虚弱的"],"answer_index":1,"explanation_cn":"robust = 强健的、结实的。✓ however lucky and robust we are."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',6,NULL,'choice','{"stem":"odds 的意思是:","options":["秩序","债务","差异","可能性,几率"],"answer_index":3,"explanation_cn":"odds = 可能性、几率。✓ the odds are heavy in favor of it."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',6,NULL,'choice','{"stem":"organism 的意思是:","options":["生物,有机体","矿物","机器","器官"],"answer_index":0,"explanation_cn":"organism = 生物、有机体。✓ other organisms such as trees."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',7,NULL,'cloze','{"stem":"第 1 空","context":"At twelve the human body is at ___1___ most vigorous, and the likelihood of death is least. The body has ___2___ to reach full strength, but already stands near the peak. The loss of vigor, ___3___ imperceptible at first, grows steep. An old body is not worth ___4___ once the living parts wear out.","blank_no":1,"options":["its","it","it''s","their"],"answer_index":0,"explanation_cn":"‘最…’= at its most + 形容词;填 its。✓ at its most vigorous."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',7,NULL,'cloze','{"stem":"第 2 空","context":"At twelve the human body is at ___1___ most vigorous, and the likelihood of death is least. The body has ___2___ to reach full strength, but already stands near the peak. The loss of vigor, ___3___ imperceptible at first, grows steep. An old body is not worth ___4___ once the living parts wear out.","blank_no":2,"options":["yet","still","ever","already"],"answer_index":0,"explanation_cn":"‘尚未…’= have yet to do;填 yet。✓ has yet to reach full strength."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',7,NULL,'cloze','{"stem":"第 3 空","context":"At twelve the human body is at ___1___ most vigorous, and the likelihood of death is least. The body has ___2___ to reach full strength, but already stands near the peak. The loss of vigor, ___3___ imperceptible at first, grows steep. An old body is not worth ___4___ once the living parts wear out.","blank_no":3,"options":["though","because","unless","since"],"answer_index":0,"explanation_cn":"‘虽然’的让步连词 though。✓ the loss of vigor, though imperceptible at first, grows steep."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',7,NULL,'cloze','{"stem":"第 4 空","context":"At twelve the human body is at ___1___ most vigorous, and the likelihood of death is least. The body has ___2___ to reach full strength, but already stands near the peak. The loss of vigor, ___3___ imperceptible at first, grows steep. An old body is not worth ___4___ once the living parts wear out.","blank_no":4,"options":["mending","mended","mend","to mend"],"answer_index":0,"explanation_cn":"worth + 动名词,‘值得修’。✓ not worth mending once the living parts wear out."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',8,NULL,'choice','{"stem":"What is one of the most unpleasant discoveries we make as we get older?","options":["That we grow stronger with age","That we will live for ever","That age has no limit","That we must gradually decline and eventually die of old age"],"answer_index":3,"explanation_cn":"录音说:我们最不愿发现的事之一,就是自己终将逐渐衰退、最终老死。✓ must decline, die of old age."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',8,NULL,'choice','{"stem":"At what age is the human body at its most vigorous, with the least likelihood of death?","options":["At about twelve years old","At sixty-five","At eighty","At birth"],"answer_index":0,"explanation_cn":"录音说:人的身体大约在十二岁最强健,死亡可能性最低。✓ at twelve, most vigorous."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',8,NULL,'choice','{"stem":"Why is human aging NOT like a run-down watch?","options":["A body has no moving parts","A watch can be rewound or mended, but a worn-out body cannot repair itself","A watch is alive","A watch never stops"],"answer_index":1,"explanation_cn":"录音说:走停的表能重新上弦或修理,而磨损的身体无法自我修复,故二者不同。✓ body cannot repair itself."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',9,NULL,'choice','{"stem":"你想说\"十二岁时人体最为强健\"(最高级 at its most):","options":["At twelve the human body is at the most vigorous of it.","At twelve the human body is at its more vigorous.","At twelve the human body is at its most vigorous.","At twelve the human body is at it most vigorous."],"answer_index":2,"explanation_cn":"最高级 at its most + 形容词;用形容词性物主代词 its(不用 it、不用 it 后置)、most 后接形容词 vigorous。✓ at its most vigorous. 场合:说“(在某方面)最…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',9,NULL,'choice','{"stem":"你想说\"科学尚未找到阻止衰老的办法\"(have yet to do):","options":["Science has yet find a way to stop aging.","Science has yet to find a way to stop aging.","Science has yet to finding a way to stop aging.","Science yet has to find a way to stop aging."],"answer_index":1,"explanation_cn":"have yet to do,‘尚未…’;yet 放在 has 之后、to 之前(不写 yet has to)、to 后接原形 find(不写 finding)、不省 to。✓ has yet to find … 场合:说“尚未做…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',9,NULL,'choice','{"stem":"你想说\"旧表磨损太甚,已不值得修理\"(worth + 动名词):","options":["The old watch is so worn that it is not worth mending.","The old watch is so worn that it is not worth mend.","The old watch is so worn that it is not worth mended.","The old watch is so worn that it is not worth to mend."],"answer_index":0,"explanation_cn":"worth + 动名词;worth 后接 mending(不用不定式 to mend、不用原形 mend、也不用过去分词 mended)。✓ not worth mending. 场合:说“(不)值得做…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"likelihood 的意思是:","options":["可能性","必然性","偶然性","重要性"],"answer_index":0,"explanation_cn":"likelihood = 可能性。✓ the likelihood of death is least."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"robust 的意思是:","options":["苗条的","虚弱的","强健的,结实的","苍白的"],"answer_index":2,"explanation_cn":"robust = 强健的、结实的。✓ however lucky and robust we are."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"\"At twelve the human body is at ___ most vigorous.\"(‘最…’= at __ most + 形容词,填形容词性物主代词)","options":["it''s","it","their","its"],"answer_index":3,"stem_cn":"十二岁时人体最为强健。","explanation_cn":"‘最…’= at its most + 形容词;填 its。✓ at its most vigorous. ✗ it / it''s / their。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"\"Science has ___ to find a way to stop aging.\"(‘尚未…’的固定说法,填那个副词)","options":["ever","soon","yet","still"],"answer_index":2,"stem_cn":"科学尚未找到阻止衰老的办法。","explanation_cn":"‘尚未…’= have yet to do;填 yet。✓ has yet to find a way. ✗ still / ever / soon。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"\"run out of\" 的意思是:","options":["装满","用完,耗尽","借来","储存"],"answer_index":1,"explanation_cn":"run out of = 用完、耗尽。✓ a wound watch runs out of energy."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"\"look after\" 的意思是:","options":["照顾,照看","跟随","抛弃","寻找"],"answer_index":0,"explanation_cn":"look after = 照顾、照看。✓ however well we look after ourselves."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"According to the passage, what is aging?","options":["A choice people make","Something only animals do","A sudden illness","The progressive loss of vigor and resistance with the passing of time"],"answer_index":3,"passage":"At the age of twelve, the human body is at its most vigorous. It has yet to reach its full size and strength, and its owner has yet to reach full intelligence; but at this age the likelihood of death is at its lowest. Earlier, as infants and small children, we were far more vulnerable; later, we shall undergo a slow, progressive loss of vigor and resistance which, though imperceptible at first, will in the end grow so steep that we can live no longer — however well we look after ourselves, and however well society and our doctors look after us. This decline in vigor with the passing of time is called aging, and it is one of the most unwelcome discoveries any of us ever makes. We all learn, sooner or later, that we must decline in this way; that if we escape wars, accidents, and disease we shall in the end ''die of old age''; and that this happens at a rate which varies little from person to person, so that the odds are heavy in favor of our dying between the ages of sixty-five and eighty. A few will die sooner, and a few will live on into a ninth or tenth decade — but the chances are against it, and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are. People tend to forget this process unless and until they are reminded of it. For years, many assumed that the steady loss of vigor was self-evident, like the cooling of a hot kettle or the wearing-out of a pair of shoes; that all animals, and perhaps other organisms such as trees, must in the nature of things wear out. It is true that most animals age much as we do, if given the chance to live long enough, and that machines like a wound watch, or the sun itself, do run out of energy. But these are not really analogous to what happens when a person ages. A run-down watch is still a watch and can be rewound; an old, worn watch, by contrast, becomes so unreliable that it is finally not worth mending. Yet a watch could never repair itself, for it has no living parts — only metal, which slowly wears away by friction. We, once, could repair ourselves, well enough at least to overcome all but the most instantly fatal illnesses; and it is precisely this power that we gradually lose between the ages of twelve and eighty.","explanation_cn":"课文说:衰老就是随时间推移、活力与抵抗力逐步丧失的过程。✓ progressive loss of vigor."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"Why can a worn-out human body not be ''mended'' like a machine?","options":["It consists of living parts that can no longer repair themselves","Machines are alive too","It has no moving parts","It is made of metal"],"answer_index":0,"passage":"At the age of twelve, the human body is at its most vigorous. It has yet to reach its full size and strength, and its owner has yet to reach full intelligence; but at this age the likelihood of death is at its lowest. Earlier, as infants and small children, we were far more vulnerable; later, we shall undergo a slow, progressive loss of vigor and resistance which, though imperceptible at first, will in the end grow so steep that we can live no longer — however well we look after ourselves, and however well society and our doctors look after us. This decline in vigor with the passing of time is called aging, and it is one of the most unwelcome discoveries any of us ever makes. We all learn, sooner or later, that we must decline in this way; that if we escape wars, accidents, and disease we shall in the end ''die of old age''; and that this happens at a rate which varies little from person to person, so that the odds are heavy in favor of our dying between the ages of sixty-five and eighty. A few will die sooner, and a few will live on into a ninth or tenth decade — but the chances are against it, and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are. People tend to forget this process unless and until they are reminded of it. For years, many assumed that the steady loss of vigor was self-evident, like the cooling of a hot kettle or the wearing-out of a pair of shoes; that all animals, and perhaps other organisms such as trees, must in the nature of things wear out. It is true that most animals age much as we do, if given the chance to live long enough, and that machines like a wound watch, or the sun itself, do run out of energy. But these are not really analogous to what happens when a person ages. A run-down watch is still a watch and can be rewound; an old, worn watch, by contrast, becomes so unreliable that it is finally not worth mending. Yet a watch could never repair itself, for it has no living parts — only metal, which slowly wears away by friction. We, once, could repair ourselves, well enough at least to overcome all but the most instantly fatal illnesses; and it is precisely this power that we gradually lose between the ages of twelve and eighty.","explanation_cn":"课文说:磨损的身体由活的部件构成,却再也无法自我修复,故不能像机器那样‘修好’。✓ living parts, no self-repair."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"Between roughly which ages are the odds heaviest that we will die of old age?","options":["After a hundred","Between about sixty-five and eighty","Between twelve and twenty","Between one and ten"],"answer_index":1,"audio":"At the age of twelve, the human body is at its most vigorous. It has yet to reach its full size and strength, and its owner has yet to reach full intelligence; but at this age the likelihood of death is at its lowest. Earlier, as infants and small children, we were far more vulnerable; later, we shall undergo a slow, progressive loss of vigor and resistance which, though imperceptible at first, will in the end grow so steep that we can live no longer — however well we look after ourselves, and however well society and our doctors look after us. This decline in vigor with the passing of time is called aging, and it is one of the most unwelcome discoveries any of us ever makes. We all learn, sooner or later, that we must decline in this way; that if we escape wars, accidents, and disease we shall in the end ''die of old age''; and that this happens at a rate which varies little from person to person, so that the odds are heavy in favor of our dying between the ages of sixty-five and eighty. A few will die sooner, and a few will live on into a ninth or tenth decade — but the chances are against it, and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are. People tend to forget this process unless and until they are reminded of it. For years, many assumed that the steady loss of vigor was self-evident, like the cooling of a hot kettle or the wearing-out of a pair of shoes; that all animals, and perhaps other organisms such as trees, must in the nature of things wear out. It is true that most animals age much as we do, if given the chance to live long enough, and that machines like a wound watch, or the sun itself, do run out of energy. But these are not really analogous to what happens when a person ages. A run-down watch is still a watch and can be rewound; an old, worn watch, by contrast, becomes so unreliable that it is finally not worth mending. Yet a watch could never repair itself, for it has no living parts — only metal, which slowly wears away by friction. We, once, could repair ourselves, well enough at least to overcome all but the most instantly fatal illnesses; and it is precisely this power that we gradually lose between the ages of twelve and eighty.","explanation_cn":"课文说:老死的概率最重地压在约六十五到八十岁之间。✓ 65 to 80."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l37',10,NULL,'choice','{"stem":"What can a young body do that an old body gradually loses the power to do?","options":["Stop the passing of time","Live for ever","Repair itself well enough to overcome all but the most fatal illnesses","Grow a whole new body"],"answer_index":2,"audio":"At the age of twelve, the human body is at its most vigorous. It has yet to reach its full size and strength, and its owner has yet to reach full intelligence; but at this age the likelihood of death is at its lowest. Earlier, as infants and small children, we were far more vulnerable; later, we shall undergo a slow, progressive loss of vigor and resistance which, though imperceptible at first, will in the end grow so steep that we can live no longer — however well we look after ourselves, and however well society and our doctors look after us. This decline in vigor with the passing of time is called aging, and it is one of the most unwelcome discoveries any of us ever makes. We all learn, sooner or later, that we must decline in this way; that if we escape wars, accidents, and disease we shall in the end ''die of old age''; and that this happens at a rate which varies little from person to person, so that the odds are heavy in favor of our dying between the ages of sixty-five and eighty. A few will die sooner, and a few will live on into a ninth or tenth decade — but the chances are against it, and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are. People tend to forget this process unless and until they are reminded of it. For years, many assumed that the steady loss of vigor was self-evident, like the cooling of a hot kettle or the wearing-out of a pair of shoes; that all animals, and perhaps other organisms such as trees, must in the nature of things wear out. It is true that most animals age much as we do, if given the chance to live long enough, and that machines like a wound watch, or the sun itself, do run out of energy. But these are not really analogous to what happens when a person ages. A run-down watch is still a watch and can be rewound; an old, worn watch, by contrast, becomes so unreliable that it is finally not worth mending. Yet a watch could never repair itself, for it has no living parts — only metal, which slowly wears away by friction. We, once, could repair ourselves, well enough at least to overcome all but the most instantly fatal illnesses; and it is precisely this power that we gradually lose between the ages of twelve and eighty.","explanation_cn":"课文说:年轻的身体曾能自我修复,足以战胜除最猝然致命者外的一切疾病,这能力随年岁渐失。✓ self-repair power."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l38',4,7,38,'Water and the Traveler','水与旅行者','be due to + 名词(由于/归因于)、Even if 引导让步(即使)、as … as(同级比较)、祈使句(Make sure … / Refuse … / Beware of …)、介词 + 关系代词(the water from which it is made)(NCE4 无 KS 页,考点由课文结构自取;IP:源为理查德·达伍德《Travellers'' Health》一篇教旅行者如何确保饮水安全的实用指南,无具名真实人物;通用公共卫生事实用 100% 原创行文复述;酒精仅作化学消毒剂/杀菌剂(科学语境),非饮用;题材=旅行健康·无害;美语化 traveler/sulfur;第四册第38课)','水源的污染,通常源于水源附近卫生条件差、污水渗入水源本身、配水系统内部污水渗漏,或工农业废物的污染。即便管道供水在起点是安全的,到达水龙头时也未必安全;而那种断断续续、时有时无的供水,更该被当作格外可疑。做短途旅行、前往水质不明之地的旅行者,应避免饮用自来水或任何来源的未处理水。最好只喝热饮,或知名品牌的瓶装、罐装饮料,因为灌装厂通常遵循国际水处理标准。碳酸饮料略带酸性,因而稍微安全些。务必确保每只瓶子都当着你的面打开,瓶口干净而干燥。烧开始终是处理水的好办法。有些旅馆应客人要求会供应开水,可用来饮用或刷牙。一只能烧开少量水的便携加热棒,只要有合适的电压就很有用。婉拒任何来源不明的冷饮,并记住:冰只和造它的水一样安全;除非确知那水是安全的,否则绝不要往饮料里加冰。给饮料降温,把容器放在冰上,远比往里面加冰要好。酒精可以充当消毒剂,但不应指望用它来给饮用水灭菌。作为一种杀菌剂,乙醇在约百分之五十到七十的浓度下效果最好;低于百分之二十,其作用微乎其微。尤其要当心工业变性酒精,它毒性极强,绝不可加进供饮用的水里。若实在找不到别的安全水源,烫得无法触碰的自来水,不妨就让它放凉,通常便可安全饮用。凡打算去偏远地区旅行、或准备在清洁饮水难得之处生活的人,都应学会各种让水变安全的方法。','{"q":"Listen and answer — What does this text describe?","options":["How travelers can keep their drinking water safe","How to build a water pipeline","The history of bottled drinks","How rivers become polluted over time"],"answer_index":0}'::jsonb,'{"title":"be due to + 名词 / Even if 让步 / as … as / 祈使句 / 介词 + 关系代词","intro":"①be due to + 名词,‘由于/归因于’。②Even if …,‘即使…’。③as … as,‘和…一样…’;not so … as,‘不像…那么…’。④祈使句用动词原形开头:Make sure …；Refuse …；Beware of …。⑤介词 + 关系代词:the water from which it is made。","table":{"headers":["用法","结构","例子"],"rows":[["be due to","be due to + 名词","contamination is due to poor sanitation"],["Even if 让步","Even if …, …","Even if it is safe at the source, …"],["as … as","as + 原级 + as","as safe as the water"],["祈使句","动词原形开头","Make sure the bottle is clean"],["介词 + 关系代词","介词 + which","the water from which it is made"]]},"specialRules":[{"rule":"due to 后接名词(be due to poor sanitation),整个 be due to 表‘由于’。","mark":"be due to + 名词"},{"rule":"肯定同级比较用 as … as;否定可用 not as … as 或 not so … as。","mark":"as … as / not so … as"},{"rule":"美式拼写:traveler(旅行者,英式 traveller)、sulfur(硫,英式 sulphur)。本课已按美语写。","mark":"traveler / sulfur"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l38',1,NULL,'Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect.','水源的污染,通常源于水源附近卫生条件差、污水渗入水源本身、配水系统内部污水渗漏,或工农业废物的污染。即便管道供水在起点是安全的,到达水龙头时也未必安全;而那种断断续续、时有时无的供水,更该被当作格外可疑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l38',2,NULL,'Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer.','做短途旅行、前往水质不明之地的旅行者,应避免饮用自来水或任何来源的未处理水。最好只喝热饮,或知名品牌的瓶装、罐装饮料,因为灌装厂通常遵循国际水处理标准。碳酸饮料略带酸性,因而稍微安全些。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l38',3,NULL,'Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available.','务必确保每只瓶子都当着你的面打开,瓶口干净而干燥。烧开始终是处理水的好办法。有些旅馆应客人要求会供应开水,可用来饮用或刷牙。一只能烧开少量水的便携加热棒,只要有合适的电压就很有用。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l38',4,NULL,'Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it.','婉拒任何来源不明的冷饮,并记住:冰只和造它的水一样安全;除非确知那水是安全的,否则绝不要往饮料里加冰。给饮料降温,把容器放在冰上,远比往里面加冰要好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l38',5,NULL,'Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.','酒精可以充当消毒剂,但不应指望用它来给饮用水灭菌。作为一种杀菌剂,乙醇在约百分之五十到七十的浓度下效果最好;低于百分之二十,其作用微乎其微。尤其要当心工业变性酒精,它毒性极强,绝不可加进供饮用的水里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l38','contamination','/kənˌtæmɪˈneɪʃn/','n','污染','contamination of a water supply') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l38','sanitation','/ˌsænɪˈteɪʃn/','n','卫生设施,环境卫生','due to poor sanitation') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
