INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','make sure','',NULL,'/meɪk ʃʊr/','Make sure the bottle is clean and dry.','务必确保瓶子干净干燥。','Make sure you boil the water.','一定要把水烧开。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','rely on','',NULL,'/rɪˈlaɪ ɑːn/','Do not rely on alcohol to sterilize water.','别指望用酒精给水灭菌。','You can rely on boiled water.','你可以放心用烧开的水。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','beware of','',NULL,'/bɪˈwer ʌv/','Beware of untreated tap-water.','当心未处理的自来水。','Beware of the dog.','当心恶犬。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','on request','',NULL,'/ɑːn rɪˈkwest/','Some hotels supply boiled water on request.','有些旅馆应客人要求供应开水。','Copies are available on request.','如有需要可索取副本。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp1','choice','{"stem":"\"Contamination of water is usually ___ to poor sanitation.\"(‘由于/归因于’= be __ to,填那个形容词)","options":["due","because","owed","thanks"],"answer_index":0,"stem_cn":"水污染通常是由差劲的卫生条件造成的。","explanation_cn":"‘由于/归因于’= be due to;填形容词 due。✓ is due to poor sanitation. ✗ owed / thanks / because:此结构用 due。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp1','choice','{"stem":"\"The outbreak was ___ to sewage leaking into the wells.\"(‘…所致’= be __ to,填那个形容词)","options":["thanks","due","since","because"],"answer_index":1,"stem_cn":"这场疫情是污水渗入水井所致。","explanation_cn":"‘…所致’= be due to;填 due。✓ was due to sewage leaking into the wells. ✗ because / since / thanks:此结构用 due。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp1','choice','{"stem":"\"Many illnesses are due ___ unsafe drinking water.\"(be due __,‘由于’,填 due 后那个介词)","options":["for","with","to","of"],"answer_index":2,"stem_cn":"许多疾病是不安全的饮用水引起的。","explanation_cn":"be due + 介词;due 后接 to。✓ are due to unsafe drinking water. ✗ of / for / with:due 搭配 to。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp2','choice','{"stem":"\"___ a piped supply is safe at its source, it may be unsafe at the tap.\"(‘即使’,让步连词)","options":["Even if","Because","So that","Unless"],"answer_index":0,"stem_cn":"即使管道水在水源处安全,到水龙头时也可能不安全。","explanation_cn":"‘即使…’的让步连词是 Even if。✓ Even if a piped supply is safe … ✗ Because / Unless / So that:‘即使’用 Even if。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp2','choice','{"stem":"\"___ the water looks clean, it may still be contaminated.\"(‘即使’,让步连词)","options":["Because","So","Unless","Even if"],"answer_index":3,"stem_cn":"即使水看起来干净,也可能已被污染。","explanation_cn":"‘即使…’用 Even if。✓ Even if the water looks clean … ✗ Because / So / Unless:‘即使’用 Even if。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp2','choice','{"stem":"\"Boil the water even ___ you are in a hurry.\"(‘即使’,even __ 结构,填 even 后那个词)","options":["that","so","if","though"],"answer_index":2,"stem_cn":"即使你赶时间,也要把水烧开。","explanation_cn":"even if 结构,even 后接 if。✓ even if you are in a hurry. ✗ though / that / so:even 后用 if。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp3','choice','{"stem":"\"Ice is only ___ safe as the water from which it is made.\"(‘和…一样…’的同级比较,填这个结构开头的那个词)","options":["more","so","than","as"],"answer_index":3,"stem_cn":"冰只和造它的水一样安全。","explanation_cn":"‘和…一样安全’= as safe as;填与后面 as 呼应的第一个 as。✓ as safe as the water. ✗ so / than / more:肯定同级比较用 as … as。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp3','choice','{"stem":"\"Bottled water is not ___ risky as untreated tap-water.\"(‘不像…那么…’= not __ … as,填与后面 as 呼应的那个词)","options":["so","than","as","more"],"answer_index":0,"stem_cn":"瓶装水不像未处理的自来水那么有风险。","explanation_cn":"‘不像…那么…’= not so … as;填第一个词 so。✓ not so risky as untreated tap-water. ✗ as / more / than:否定可用 not so … as。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp3','choice','{"stem":"\"Boiled water is just as ___ as fresh spring water.\"(as + 形容词 + as,填形容词)","options":["safest","safe","safer","safely"],"answer_index":1,"stem_cn":"烧开的水和新鲜泉水一样安全。","explanation_cn":"as + 形容词 + as,填形容词原级 safe。✓ just as safe as fresh spring water. ✗ safer(比较级)/ safest(最高级)/ safely(副词):as … as 中间用原级。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp4','choice','{"stem":"\"___ sure that all bottles are opened in your presence.\"(祈使句,‘务必确保’,填动词原形)","options":["Make","To make","Making","Made"],"answer_index":0,"stem_cn":"务必确保所有瓶子当着你的面打开。","explanation_cn":"祈使句用动词原形开头;‘务必确保’用 Make(sure)。✓ Make sure that all bottles are opened … ✗ Making / Made / To make:祈使句用动词原形。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp4','choice','{"stem":"\"___ politely any cold drink from an unknown source.\"(祈使句,‘婉拒’,填动词原形)","options":["To refuse","Refusing","Refused","Refuse"],"answer_index":3,"stem_cn":"婉拒任何来源不明的冷饮。","explanation_cn":"祈使句用动词原形开头;‘婉拒’用 Refuse。✓ Refuse politely any cold drink … ✗ Refusing / Refused / To refuse:祈使句用动词原形。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp4','choice','{"stem":"\"___ of methylated alcohol, which is very poisonous.\"(祈使句,‘当心’,填动词原形)","options":["Beware","Bewaring","Bewared","To beware"],"answer_index":0,"stem_cn":"当心工业变性酒精,它毒性很强。","explanation_cn":"祈使句用动词原形开头;‘当心’用 Beware(of)。✓ Beware of methylated alcohol … ✗ Bewaring / Bewared / To beware:祈使句用动词原形。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp5','choice','{"stem":"\"The water ___ which the ice is made must be safe.\"(介词+关系代词;‘用…制成’,填与 make 搭配表‘用…’的那个介词)","options":["by","from","of","at"],"answer_index":1,"stem_cn":"用来制冰的水必须是安全的。","explanation_cn":"介词 + 关系代词;‘用…制成’是 make from,介词用 from。✓ the water from which the ice is made. ✗ of / at / by:make 搭配 from。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp5','choice','{"stem":"\"The source ___ which the disease spread was the well.\"(介词+关系代词;‘从…扩散’,填与 spread 搭配的那个介词)","options":["from","at","in","of"],"answer_index":0,"stem_cn":"疾病扩散的源头是那口井。","explanation_cn":"介词 + 关系代词;‘从…扩散’是 spread from,介词用 from。✓ the source from which the disease spread. ✗ of / at / in:spread 搭配 from。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp5','choice','{"stem":"\"The bottle ___ which you drink should be clean.\"(介词+关系代词;‘从其中饮用’,填与 drink 搭配的那个介词)","options":["at","of","on","from"],"answer_index":3,"stem_cn":"你所饮用的那只瓶子应当是干净的。","explanation_cn":"介词 + 关系代词;‘从其中饮用’是 drink from,介词用 from。✓ the bottle from which you drink. ✗ of / at / on:drink 搭配 from。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp6','choice','{"stem":"\"The presence of harmful or dirty substances in water is ___.\"(“污染”用哪个词)","options":["contamination","celebration","cooperation","conversation"],"answer_index":0,"stem_cn":"水中存在有害或肮脏物质。","explanation_cn":"水中存在有害或肮脏物质是 contamination(污染)。✓ the presence of harmful substances is contamination. ✗ celebration 庆祝;✗ cooperation 合作;✗ conversation 交谈——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp6','choice','{"stem":"\"A substance used to destroy harmful germs is a ___.\"(“消毒剂”用哪个词)","options":["instrument","disinfectant","apartment","ingredient"],"answer_index":1,"stem_cn":"用来杀灭有害病菌的物质。","explanation_cn":"用来杀灭有害病菌的物质是 disinfectant(消毒剂)。✓ a substance to destroy germs is a disinfectant. ✗ ingredient 原料;✗ instrument 器械;✗ apartment 公寓——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp6','choice','{"stem":"\"To make something free from germs is to ___ it.\"(“消毒,灭菌”用哪个词)","options":["apologize","organize","memorize","sterilize"],"answer_index":3,"stem_cn":"使某物无菌。","explanation_cn":"使某物无菌是 sterilize(消毒、灭菌)。✓ to make something free from germs is to sterilize. ✗ memorize 记住;✗ apologize 道歉;✗ organize 组织——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"contamination 的意思是:","options":["凝结","净化","污染","蒸发"],"answer_index":2,"explanation_cn":"contamination = 污染。✓ contamination of a water supply."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"sanitation 的意思是:","options":["交通","教育","娱乐","卫生设施,环境卫生"],"answer_index":3,"explanation_cn":"sanitation = 卫生设施、环境卫生。✓ due to poor sanitation."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"sewage 的意思是:","options":["海水","泉水","污水,下水道污物","雨水"],"answer_index":2,"explanation_cn":"sewage = 污水、下水道污物。✓ sewage seeping into the source."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"intermittent 的意思是:","options":["迅速的","间歇的,断断续续的","永久的","持续的"],"answer_index":1,"explanation_cn":"intermittent = 间歇的、断断续续的。✓ an intermittent supply is suspect."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"sterilize 的意思是:","options":["消毒,灭菌","冷冻","加热","污染"],"answer_index":0,"explanation_cn":"sterilize = 消毒、灭菌。✓ should not be relied upon to sterilize water."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"acidic 的意思是:","options":["中性的","甜的","碱性的","酸性的"],"answer_index":3,"explanation_cn":"acidic = 酸性的。✓ carbonated drinks are slightly acidic."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 1 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":1,"options":["due","because","since","thanks"],"answer_index":0,"explanation_cn":"‘由于/归因于’= be due to;填 due。✓ is due to poor sanitation."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 2 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":2,"options":["Even if","Because","Unless","So"],"answer_index":0,"explanation_cn":"‘即使…’的让步连词是 Even if。✓ Even if a piped supply is safe at its source …"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 3 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":3,"options":["as","so","than","more"],"answer_index":0,"explanation_cn":"‘和…一样安全’= as safe as;填第一个 as。✓ as safe as the water from which it is made."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 4 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":4,"options":["Make","Making","Made","To make"],"answer_index":0,"explanation_cn":"祈使句用动词原形开头,‘务必确保’用 Make。✓ Make sure that every bottle is opened …"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',8,NULL,'choice','{"stem":"What does this text mainly describe?","options":["The history of bottled drinks","How rivers become polluted over time","How travelers can keep their drinking water safe","How to build a water pipeline"],"answer_index":2,"explanation_cn":"录音说:本文讲的是旅行者如何确保饮用水安全。✓ keeping drinking water safe."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',8,NULL,'choice','{"stem":"Why may piped water be unsafe even if it is safe at its source?","options":["Source water is never safe","The pipes add minerals","It is always boiled first","It can be contaminated on the way to the tap, by leaking sewage or waste"],"answer_index":3,"explanation_cn":"录音说:即使水源安全,水在流向龙头途中也可能因污水渗漏或废物而受污染。✓ contaminated on the way."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',8,NULL,'choice','{"stem":"What is always a good way of treating water, according to the text?","options":["Boiling it","Adding alcohol to it","Freezing it","Shaking it hard"],"answer_index":0,"explanation_cn":"录音说:烧开始终是处理水、使之安全的好办法。✓ boiling is a good way."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',9,NULL,'choice','{"stem":"你想说\"水污染通常是由差劲的卫生条件造成的\"(be due to):","options":["Contamination of water is usually owing poor sanitation.","Contamination of water is usually due of poor sanitation.","Contamination of water is usually due poor sanitation.","Contamination of water is usually due to poor sanitation."],"answer_index":3,"explanation_cn":"be due to + 名词,‘由于’;due 后接 to(不写 due poor、不写 due of)、也不用 owing 少 to。✓ due to poor sanitation. 场合:说“…是由…造成的”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',9,NULL,'choice','{"stem":"你想说\"即使管道水在水源处是安全的,到水龙头时也可能不安全\"(Even if 让步):","options":["Even though if a piped supply is safe at its source, it may be unsafe at the tap.","Even if a piped supply is safe at its source, it may be unsafe at the tap.","Even if a piped supply is safe at its source, but it may be unsafe at the tap.","Even a piped supply is safe at its source, it may be unsafe at the tap."],"answer_index":1,"explanation_cn":"Even if 引导让步,‘即使’;不能省 if(不写 Even a piped…)、主句不再加 but(不写 Even if…, but…)、也不写 Even though if。✓ Even if …, … 场合:说“即使…也…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',9,NULL,'choice','{"stem":"你想说\"冰只和造它的水一样安全\"(as … as):","options":["Ice is only as safe than the water from which it is made.","Ice is only so safe as the water from which it is made.","Ice is only as safe as the water from which it is made.","Ice is only as safe as the water from which it is make."],"answer_index":2,"explanation_cn":"as … as 同级比较;两个都用 as(不写 as … than)、肯定句不用 so … as、从句 it is made 用被动(不写 it is make)。✓ as safe as … 场合:说“和…一样…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"contamination 的意思是:","options":["蒸发","净化","凝结","污染"],"answer_index":3,"explanation_cn":"contamination = 污染。✓ contamination of a water supply."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"sterilize 的意思是:","options":["加热","消毒,灭菌","冷冻","污染"],"answer_index":1,"explanation_cn":"sterilize = 消毒、灭菌。✓ should not be relied upon to sterilize water."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"Contamination of water is usually ___ to poor sanitation.\"(‘由于/归因于’= be __ to,填那个词)","options":["because","since","thanks","due"],"answer_index":3,"stem_cn":"水污染通常由差劲的卫生条件造成。","explanation_cn":"‘由于/归因于’= be due to;填 due。✓ due to poor sanitation. ✗ because / since / thanks。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"___ a piped supply is safe at its source, it may be unsafe at the tap.\"(‘即使’,让步连词)","options":["Unless","Even if","Because","So"],"answer_index":1,"stem_cn":"即使管道水在水源处安全,到水龙头时也可能不安全。","explanation_cn":"‘即使…’的让步连词是 Even if。✓ Even if a piped supply is safe … ✗ Because / Unless / So。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"make sure\" 的意思是:","options":["拒绝","怀疑","确保,查明","忘记"],"answer_index":2,"explanation_cn":"make sure = 确保、查明。✓ make sure the bottle is clean."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"beware of\" 的意思是:","options":["喜爱","当心,提防","接受","忽视"],"answer_index":1,"explanation_cn":"beware of = 当心、提防。✓ beware of untreated tap-water."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"According to the text, why should intermittent tap-water supplies be treated as especially suspect?","options":["The on-and-off flow makes contamination more likely","They taste bad","They are always cold","They cost more"],"answer_index":0,"passage":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:时有时无的供水更易被污染,故格外可疑。✓ intermittent supply suspect."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"What does the text advise travelers to drink in areas with unsafe water?","options":["Water straight from a river","Any cold drink offered to them","Hot drinks, or bottled or canned drinks of well-known brands","Untreated tap-water"],"answer_index":2,"passage":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:水质不明之地,旅行者应喝热饮或知名品牌瓶装/罐装饮料。✓ hot drinks, bottled brands."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"Why is ice a possible danger?","options":["It is made of sewage","It cools drinks too much","It is always dirty","It is only as safe as the water it is made from"],"answer_index":3,"audio":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:冰只和造它的水一样安全,故来源不明的冰有危险。✓ ice as safe as its water."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"According to the text, how safe is alcohol for sterilizing drinking water?","options":["It should not be relied upon to sterilize water","It is completely harmless in any form","It is the best sterilizer","It always makes water safe"],"answer_index":0,"audio":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:酒精虽可作消毒剂,却不应被指望用来给饮用水灭菌。✓ not relied upon to sterilize."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l39',4,7,39,'What Every Writer Wants','作家都想要什么','whom 引导定语从句(指人作宾语)、once 引导时间从句(一旦/一…就…)、might as well do(还不如/不妨)、till/until + 现在完成(will not rest till he has captured it)、be of + 抽象名词(= 形容词:of an indescribable fascination)(NCE4 无 KS 页,考点由课文结构自取;IP:源为约翰·勒卡雷《What Every Writer Wants》一篇论写作过程的第一人称随笔,是署名版权作品——已用 100% 原创行文复述其观点、无具名、克什米尔具体轶事已泛化;题材=写作艺术·无害;美语化 draft/practice;第四册第39课)','我认识的作家很少,但我认识、且敬重的那几位,都会立刻坦白:动笔之初,他们几乎不知道自己要写向何方。他们心里有一个人物,也许两个;他们处在那种急切又不安的状态里,那被人当作灵感;而且他们全都承认,一旦旅程开始,目的地会发生根本的改变。据我确知,有一位在一部背景设在某个遥远国度的小说上花了九个月,随后又悄悄把整个故事挪到了另一个地方。我从没听说谁真去搭建我们在学校里学的那种齐整的‘骨架’。在拆了又搭、在推敲时序、在交织穿插、在从头再来的过程中,作家渐渐在自己的素材里辨认出一些动笔时并未有意识地想到的东西。这个有机的过程,常常通向非凡的自我发现,有着难以言说的魅力。一个模糊的影像浮现出来;他添一笔,再添一笔,它却消失了;可那里确曾有过什么,不把它捉住,他便不肯歇息。有时,作家体内那股‘酵母’,比他写成的书活得还久。据说有的作家除了自己的书什么都不读;就像照镜子的青少年,他们始终看不清眼前那幅景象的确切轮廓。出于同样的缘故,作家们没完没了地谈论自己的作品,挑拣出隐藏的含义、又层层叠上新的,向身边每个人乞求回应。这样做的作家会被误解——他还不如去解释一桩罪案,或一段情事——而且顺便说一句,他还是个不可饶恕的讨厌鬼。一位年轻作家曾说过一句中肯的话:才华用在初稿里,艺术用在其后的一稿又一稿里。也正因如此,作家和任何别的艺术家一样,没有歇脚之处,没有可供他寻求慰藉的人群或潮流,没有任何来自外部、能取代内心裁断的评判。他要从自己内心的混沌中理出秩序;他让自己服从于比任何评论家所梦想的都更冷酷的纪律;而当他与名声调情时,他不过是从探寻自己世界最深处那一点的路上,偷得片刻的闲。','{"q":"Listen and answer — How do professional writers ignore what they were taught at school about writing?","options":["They make no ''skeleton'' or plan, but discover the shape as they write","They never revise anything","They copy other writers","They write only about school"],"answer_index":0}'::jsonb,'{"title":"whom 定语从句 / once 时间从句 / might as well do / till + 现在完成 / be of + 抽象名词","intro":"①whom 引导定语从句,指人、在从句里作宾语。②once 引导时间从句,‘一旦/一…就…’。③might as well do,‘还不如/不妨’；might as well A as B,‘做A无异于做B’。④till/until 从句表将来时用现在完成:will not rest till he has captured it。⑤be of + 抽象名词 = 形容词:of an indescribable fascination = fascinating。","table":{"headers":["用法","结构","例子"],"rows":[["whom 定语从句","先行词(人)+ whom + …","those whom I respect"],["once 时间从句","Once …, …","once the journey has begun"],["might as well do","might as well + 原形","might as well try to explain a crime"],["till + 现在完成","will not … till + 现在完成","will not rest till he has captured it"],["be of + 抽象名词","be of + 名词(=形容词)","of an indescribable fascination"]]},"specialRules":[{"rule":"定语从句中指人、作宾语时用 whom(可省略或用 who 代替);作主语用 who。","mark":"whom(作宾语)"},{"rule":"till/until、once 等时间从句里,表将来的动作常用现在完成时,不用 will。","mark":"till he has done"},{"rule":"美式拼写:draft(草稿,英式 draught)、practice(练习,英式动词 practise)。本课已按美语写。","mark":"draft / practice"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l39',1,NULL,'I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun.','我认识的作家很少,但我认识、且敬重的那几位,都会立刻坦白:动笔之初,他们几乎不知道自己要写向何方。他们心里有一个人物,也许两个;他们处在那种急切又不安的状态里,那被人当作灵感;而且他们全都承认,一旦旅程开始,目的地会发生根本的改变。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l39',2,NULL,'One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began.','据我确知,有一位在一部背景设在某个遥远国度的小说上花了九个月,随后又悄悄把整个故事挪到了另一个地方。我从没听说谁真去搭建我们在学校里学的那种齐整的‘骨架’。在拆了又搭、在推敲时序、在交织穿插、在从头再来的过程中,作家渐渐在自己的素材里辨认出一些动笔时并未有意识地想到的东西。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l39',3,NULL,'This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it.','这个有机的过程,常常通向非凡的自我发现,有着难以言说的魅力。一个模糊的影像浮现出来;他添一笔,再添一笔,它却消失了;可那里确曾有过什么,不把它捉住,他便不肯歇息。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l39',4,NULL,'Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore.','有时,作家体内那股‘酵母’,比他写成的书活得还久。据说有的作家除了自己的书什么都不读;就像照镜子的青少年,他们始终看不清眼前那幅景象的确切轮廓。出于同样的缘故,作家们没完没了地谈论自己的作品。这样做的作家会被误解——他还不如去解释一桩罪案,或一段情事——而且顺便说一句,他还是个不可饶恕的讨厌鬼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l39',5,NULL,'A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.','一位年轻作家曾说过一句中肯的话:才华用在初稿里,艺术用在其后的一稿又一稿里。也正因如此,作家和任何别的艺术家一样,没有歇脚之处,没有可供他寻求慰藉的人群或潮流,没有任何来自外部、能取代内心裁断的评判。他要从自己内心的混沌中理出秩序;他让自己服从于比任何评论家所梦想的都更冷酷的纪律;而当他与名声调情时,他不过是从探寻自己世界最深处那一点的路上,偷得片刻的闲。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
