INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','set pen to paper','',NULL,'/set pen tuː ˈpeɪpər/','As soon as he set pen to paper, ideas came.','他一动笔,想法就涌来。','I couldn''t set pen to paper all day.','我一整天都写不出一个字。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','come to','',NULL,'/kʌm tuː/','The writer comes to discern hidden things.','作家渐渐辨认出隐藏的东西。','She came to love the quiet city.','她渐渐爱上了这座安静的城市。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','take comfort in','',NULL,'/teɪk ˈkʌmfərt ɪn/','He takes comfort in his own work.','他从自己的作品中得到慰藉。','We took comfort in her kind words.','她温暖的话语给了我们安慰。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','make order out of','',NULL,'/meɪk ˈɔːrdər aʊt ʌv/','A writer makes order out of the anarchy of his heart.','作家从内心的混沌中理出秩序。','She made order out of the chaos.','她把一团乱理出了头绪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp1','choice','{"stem":"\"The writers ___ I respect confess they don''t know where they are going.\"(定语从句先行词指人、作宾语,填关系词)","options":["whose","whom","what","which"],"answer_index":1,"stem_cn":"我所敬重的那些作家,承认自己不知去向何方。","explanation_cn":"定语从句先行词指人、在从句里作宾语,用 whom。✓ the writers whom I respect. ✗ which(指物)/ whose(所有格)/ what(不引导定从):指人作宾语用 whom。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp1','choice','{"stem":"\"He is a writer ___ everyone admires but few understand.\"(定语从句指人、作宾语,填关系词)","options":["whom","what","whose","which"],"answer_index":0,"stem_cn":"他是个人人钦佩、却少有人读懂的作家。","explanation_cn":"定语从句指人、作宾语,用 whom。✓ a writer whom everyone admires. ✗ which / whose / what:指人作宾语用 whom。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp1','choice','{"stem":"\"The reader for ___ he writes may never truly know him.\"(介词 + 关系代词,指人作宾语,填关系词)","options":["which","that","whom","who"],"answer_index":2,"stem_cn":"他为之写作的读者,也许永远不会真正了解他。","explanation_cn":"介词 + 关系代词,指人作宾语,介词后只能用 whom。✓ the reader for whom he writes. ✗ which / who(介词后不用 who)/ that(介词后不用 that):for + whom。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp2','choice','{"stem":"\"___ the journey has begun, the destination often changes.\"(‘一旦…就…’,填时间连词)","options":["Although","Once","Unless","Because"],"answer_index":1,"stem_cn":"旅程一旦开始,目的地往往就变了。","explanation_cn":"‘一旦…就…’的时间连词是 Once。✓ Once the journey has begun … ✗ Unless 除非 / Because 因为 / Although 虽然:‘一旦’用 Once。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp2','choice','{"stem":"\"A story takes on a life of its own ___ the writer sets pen to paper.\"(‘一…就…’,填时间连词)","options":["so","unless","because","once"],"answer_index":3,"stem_cn":"作家一动笔,故事便有了自己的生命。","explanation_cn":"‘一…就…’用 once。✓ once the writer sets pen to paper. ✗ unless / because / so:‘一…就’用 once。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp2','choice','{"stem":"\"___ he has captured the image, he can rest at last.\"(‘一旦…’,填时间连词)","options":["Unless","Because","Once","Whether"],"answer_index":2,"stem_cn":"一旦捕捉到那个意象,他终于可以歇息。","explanation_cn":"‘一旦…’用 Once。✓ Once he has captured the image … ✗ Unless / Because / Whether:‘一旦’用 Once。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp3','choice','{"stem":"\"A writer explaining his own book might as ___ try to explain a crime.\"(might as __ do,‘还不如/不妨’,填 as 后那个词)","options":["well","good","best","better"],"answer_index":0,"stem_cn":"作家解释自己的书,还不如去解释一桩罪案。","explanation_cn":"might as well do,‘还不如/不妨’;固定搭配填 well。✓ might as well try to explain a crime. ✗ good / better / best:此结构用 well。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp3','choice','{"stem":"\"Since no one is listening, we might as well ___ home.\"(might as well + 动词原形,填原形)","options":["going","to go","went","go"],"answer_index":3,"stem_cn":"既然没人在听,我们不如回家。","explanation_cn":"might as well + 动词原形;填原形 go。✓ we might as well go home. ✗ going / went / to go:might as well 后接原形。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp3','choice','{"stem":"\"You might ___ well ask the wind to stop as ask him to explain his art.\"(‘做A无异于做B’这个结构,填 might 后紧跟的那个词)","options":["too","very","as","so"],"answer_index":2,"stem_cn":"让他解释自己的艺术,无异于让风停下。","explanation_cn":"‘做A无异于做B’= might as well A as B;填 might 后紧跟的那个词。✓ might as well ask the wind to stop as … ✗ so / too / very:此结构该位置用 as。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp4','choice','{"stem":"\"The writer will not rest ___ he has captured the image.\"(‘直到…’,填时间连词)","options":["till","so","unless","because"],"answer_index":0,"stem_cn":"不捕捉到那个意象,作家便不肯歇息。","explanation_cn":"‘直到…’的时间连词是 till。✓ will not rest till he has captured it. ✗ unless 除非 / because 因为 / so 所以:‘直到’用 till。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp4','choice','{"stem":"\"Do not judge the book until you ___ read the final draft.\"(until 从句用现在完成,填助动词)","options":["will","have","did","are"],"answer_index":1,"stem_cn":"读完终稿之前,别评判这本书。","explanation_cn":"until/till 从句表将来时用现在完成;填助动词 have。✓ until you have read the final draft. ✗ will(从句不用 will)/ are / did:现在完成用 have + 过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp4','choice','{"stem":"\"He kept rewriting till the story ___ found its true shape.\"(till 从句用现在完成,填助动词)","options":["had","does","is","will"],"answer_index":0,"stem_cn":"他不停重写,直到故事找到它真正的形状。","explanation_cn":"till 从句里跟随主句过去时,用过去完成;填助动词 had。✓ kept rewriting till the story had found its shape. ✗ will / is / does:此处用 had found。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp5','choice','{"stem":"\"This organic process is ___ an indescribable fascination.\"(be __ + 抽象名词,相当于形容词,‘极其迷人’,填那个介词)","options":["at","for","in","of"],"answer_index":3,"stem_cn":"这一有机的过程,有着难以言说的魅力。","explanation_cn":"be of + 抽象名词 = 形容词;填介词 of。✓ is of an indescribable fascination(= fascinating). ✗ in / at / for:此结构用 of。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp5','choice','{"stem":"\"His remark was of great ___ to every young writer.\"(be of + 抽象名词,‘很有价值’,填那个名词)","options":["value","values","valued","valuable"],"answer_index":0,"stem_cn":"他的话对每个年轻作家都极有价值。","explanation_cn":"be of + 抽象名词,‘很有价值’= of great value;填名词 value。✓ was of great value. ✗ valuable(形容词)/ valued / values:be of 后接名词 value。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp5','choice','{"stem":"\"A first draft is often of little ___ until it is remade.\"(be of + 抽象名词,‘没什么用’,填那个名词)","options":["used","uses","use","useful"],"answer_index":2,"stem_cn":"初稿在重写之前往往没什么用。","explanation_cn":"be of + 抽象名词,‘没什么用’= of little use;填名词 use。✓ of little use until it is remade. ✗ useful(形容词)/ used / uses:be of 后接名词 use。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp6','choice','{"stem":"\"To admit something, especially reluctantly, is to ___ it.\"(“坦白,承认”用哪个词)","options":["connect","confess","confuse","conceal"],"answer_index":1,"stem_cn":"(尤指不情愿地)承认某事。","explanation_cn":"(尤指不情愿地)承认某事是 confess(坦白、承认)。✓ to admit reluctantly is to confess. ✗ conceal 隐瞒;✗ confuse 使糊涂;✗ connect 连接——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp6','choice','{"stem":"\"A sudden brilliant idea that drives creative work is ___.\"(“灵感”用哪个词)","options":["inspiration","hesitation","isolation","imitation"],"answer_index":0,"stem_cn":"驱动创作的突发妙想。","explanation_cn":"驱动创作的突发妙想是 inspiration(灵感)。✓ a sudden brilliant idea is inspiration. ✗ imitation 模仿;✗ hesitation 犹豫;✗ isolation 孤立——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp6','choice','{"stem":"\"To make out or perceive something with difficulty is to ___ it.\"(“看出,辨别”用哪个词)","options":["disturb","dismiss","dissolve","discern"],"answer_index":3,"stem_cn":"费力地看出或觉察到某物。","explanation_cn":"费力地看出或觉察到某物是 discern(看出、辨别)。✓ to perceive with difficulty is to discern. ✗ dismiss 打发;✗ disturb 打扰;✗ dissolve 溶解——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"confess 的意思是:","options":["隐瞒","夸耀","坦白,承认","否认"],"answer_index":2,"explanation_cn":"confess = 坦白、承认。✓ they confess at once."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"inspiration 的意思是:","options":["模仿","疲惫","犹豫","灵感"],"answer_index":3,"explanation_cn":"inspiration = 灵感。✓ that passes for inspiration."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"discern 的意思是:","options":["看出,辨别","隐藏","破坏","忽视"],"answer_index":0,"explanation_cn":"discern = 看出、辨别。✓ comes to discern things in his material."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"indescribable 的意思是:","options":["平凡的","难以形容的","短暂的","清晰的"],"answer_index":1,"explanation_cn":"indescribable = 难以形容的。✓ of an indescribable fascination."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"fathom 的意思是:","options":["编造","误解","忘记","彻底理解,看透"],"answer_index":3,"explanation_cn":"fathom = 彻底理解、看透。✓ cannot fathom the exact outline."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"pertinent 的意思是:","options":["中肯的,相关的","错误的","多余的","无关的"],"answer_index":0,"explanation_cn":"pertinent = 中肯的、相关的。✓ a pertinent observation."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 1 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":1,"options":["whom","which","whose","what"],"answer_index":0,"explanation_cn":"定语从句指人、作宾语,用 whom。✓ the writers whom I respect."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 2 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":2,"options":["Once","Unless","Because","Although"],"answer_index":0,"explanation_cn":"‘一旦…就…’的时间连词是 Once。✓ Once the journey has begun …"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 3 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":3,"options":["well","good","better","best"],"answer_index":0,"explanation_cn":"might as well do,‘还不如’;固定搭配填 well。✓ might as well try to explain a crime."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 4 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":4,"options":["of","in","at","for"],"answer_index":0,"explanation_cn":"be of + 抽象名词 = 形容词;填 of。✓ is of an indescribable fascination."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',8,NULL,'choice','{"stem":"How do professional writers ignore what they were taught at school about writing?","options":["They copy other writers","They make no ''skeleton'' or plan, but discover the shape as they write","They never revise anything","They write only about school"],"answer_index":1,"explanation_cn":"录音说:职业作家不搭学校教的‘骨架’,而是边写边发现作品的形状。✓ no skeleton, discover as they write."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',8,NULL,'choice','{"stem":"According to the writer, where does the real art of writing go?","options":["Into pleasing the reader","Into reading one''s own books","Into the drafts that follow the first one","Into the very first draft only"],"answer_index":2,"explanation_cn":"录音说:才华进初稿,艺术进其后的一稿又一稿。✓ art into the later drafts."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',8,NULL,'choice','{"stem":"Why is a writer who talks endlessly about his own books an ''unforgivable bore''?","options":["Explaining his work is as pointless as explaining a crime or a love affair","He has nothing else to say","He hates his readers","He cannot write any more"],"answer_index":0,"explanation_cn":"录音说:解释自己的作品和解释一桩罪案或一段情事一样徒劳,故成了讨厌鬼。✓ as pointless as explaining a crime."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',9,NULL,'choice','{"stem":"你想说\"旅程一旦开始,目的地往往就变了\"(once 引导时间从句):","options":["Once the journey has begun, but the destination often changes.","Once the journey will begin, the destination often changes.","As once the journey has begun, the destination often changes.","Once the journey has begun, the destination often changes."],"answer_index":3,"explanation_cn":"once 引导时间从句,‘一旦…就…’;从句用现在完成 has begun、主句不再加 but(不写 Once…, but…)、once 前不加 As。✓ Once …, … 场合:说“一旦…就…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',9,NULL,'choice','{"stem":"你想说\"作家解释自己的书,还不如去解释一桩罪案\"(might as well):","options":["A writer explaining his book might as well try to explain a crime.","A writer explaining his book might as well trying to explain a crime.","A writer explaining his book might as good try to explain a crime.","A writer explaining his book might well as try to explain a crime."],"answer_index":0,"explanation_cn":"might as well + 动词原形 try(不用 trying)、well 不写成 good、词序是 as well(不写 well as)。✓ might as well try … 场合:说“还不如/不妨做…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',9,NULL,'choice','{"stem":"你想说\"这一有机的过程,有着难以言说的魅力\"(be of + 抽象名词):","options":["This organic process is with an indescribable fascination.","This organic process is an indescribable fascination of.","This organic process is of an indescribable fascination.","This organic process of an indescribable fascination is."],"answer_index":2,"explanation_cn":"be of + 抽象名词,‘极其迷人’;of 紧跟 be 之后(不后置)、不用 with 代替 of。✓ is of an indescribable fascination. 场合:说“(某物)具有某种性质”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"confess 的意思是:","options":["坦白,承认","否认","隐瞒","夸耀"],"answer_index":0,"explanation_cn":"confess = 坦白、承认。✓ they confess at once."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"inspiration 的意思是:","options":["犹豫","灵感","疲惫","模仿"],"answer_index":1,"explanation_cn":"inspiration = 灵感。✓ that passes for inspiration."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"The writers ___ I respect confess they don''t know where they are going.\"(定语从句指人、作宾语)","options":["whom","which","whose","what"],"answer_index":0,"stem_cn":"我所敬重的作家承认不知去向。","explanation_cn":"定语从句指人、作宾语,用 whom。✓ the writers whom I respect. ✗ which / whose / what。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"___ the journey has begun, the destination often changes.\"(‘一旦…就…’,时间连词)","options":["Although","Once","Unless","Because"],"answer_index":1,"stem_cn":"旅程一旦开始,目的地往往就变。","explanation_cn":"‘一旦…就…’的时间连词是 Once。✓ Once the journey has begun … ✗ Unless / Because / Although。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"set pen to paper\" 的意思是:","options":["收起笔","朗读","撕掉纸","动笔,开始写作"],"answer_index":3,"explanation_cn":"set pen to paper = 动笔、开始写作。✓ when they first set pen to paper."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"take comfort in\" 的意思是:","options":["离开…","从…中得到安慰","破坏…","抱怨…"],"answer_index":1,"explanation_cn":"take comfort in = 从…中得到安慰。✓ a crowd in which he may take comfort."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"According to the writer, what happens once a writer sets pen to paper?","options":["He copies what he learned at school","He follows a fixed ''skeleton'' to the end","He often makes radical changes of destination as the work grows","He stops after the first page"],"answer_index":2,"passage":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"课文说:作家一动笔,常随作品生长而彻底改变原定的方向。✓ radical changes of destination."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"Why can the wish to please the reader be a writer''s ''undoing''?","options":["It wastes paper","He starts writing to please others instead of making order out of his own heart","It makes him famous too fast","Readers dislike being pleased"],"answer_index":1,"passage":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"课文说:讨好读者之心会成为作家的败因,因为他转而为取悦别人而写,而非从内心的混沌中理出秩序。✓ writing to please, his undoing."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"What did a young writer observe about talent and art?","options":["Talent and art are the same thing","Art comes first, then talent","Neither matters at all","Talent goes into the first draft, and art into the drafts that follow"],"answer_index":3,"audio":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"录音里那位年轻作家说:才华用在初稿,艺术用在其后一稿又一稿。✓ talent first draft, art later."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"What kind of discipline does a real writer submit himself to?","options":["The judgment of the crowd","A more ruthless discipline than any critic ever dreamed of","No discipline at all","Only the rules taught at school"],"answer_index":1,"audio":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"课文说:真正的作家让自己服从于比任何评论家所梦想的都更冷酷的纪律。✓ more ruthless than any critic."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l40',4,7,40,'Waves','海浪','与事实相反的虚拟条件(If the water was moving …, everything would be racing …)、cause sb/sth to do(使…做)、现在分词作状语(awakening it to flow / leaving the water where it was)、it takes sth/sb + time + to do(某物做某事需要…时间)、现在完成被动(Once the waves have been generated)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 BBC World Magazine 一篇讲海浪成因与运动的科普文,系版权作品——已用 100% 原创行文复述其事实、无引用原句;题材=海洋物理·无害;美语化 meter/center;第四册第40课,PDF 内误标为 Lesson 39)','海浪是海洋与大气之间那场漫长搏斗的孩子。太阳的光线为空气注入能量,唤醒它流动、运动;风随后把太阳的讯息带给大海,大海又通过波浪把它传递下去。这些海浪是一切自然现象中最复杂的之一。每一道浪都有一个波峰——浪的最高点,和一个波谷——最低点;它的浪高是从波谷到波峰的垂直距离,浪长是两个相邻波峰之间的水平距离,而周期则是一个波峰走过一个波长所需的时间。虽然一道海浪给你的印象,是一堵水墙正朝你的方向涌来,实际上浪是穿过水而行的,把水大致留在它原来的地方。假如水真的随浪一起移动,大海连同上面的一切都会冲向海岸,后果显然是灾难性的。一道穿过深水的海浪,使水面上的一个微粒沿着大致圆形的轨道运动:先把它拉向前进中的浪,再送它上到浪里,随浪向前,然后——当浪把这个微粒抛在身后——又回到它出发的那一点。从诞生到消亡,一道浪都受制于和任何别的活物一样的规律。有一阵子它显出一种奇异的个性,而后,到最后,它又被重新吸纳进它来自的那片浩瀚海洋。外海那些起伏的波浪由三种自然的力量生成:风,大地的运动或震颤,以及月亮和太阳的引力。而一旦波浪已经生成,重力便成了驱使它们前行的力量,不停地试图把海面重新恢复为平坦、齐整的一片。','{"q":"Listen and answer — What false impression does an ocean wave convey to the observer?","options":["That a wall of water is moving toward the shore, though the water itself stays about where it was","That the sea is completely still","That the water races along with the wave","That waves never move at all"],"answer_index":0}'::jsonb,'{"title":"虚拟条件 would / cause sb to do / 现在分词作状语 / it takes sth time to do / 现在完成被动","intro":"①与事实相反的虚拟条件:If + 过去式,主句 would + 动词原形。②cause sb/sth to do,‘使某人/某物做…’,to 不能省。③现在分词作状语,表伴随:awakening it to flow。④it takes sth/sb + time + to do,‘某物做某事需要…时间’。⑤现在完成被动:have/has been + 过去分词。","table":{"headers":["用法","结构","例子"],"rows":[["虚拟条件","If + 过去式, would + 原形","If the water was moving…, it would race…"],["cause sb to do","cause + 宾语 + to do","causes a particle to move"],["现在分词作状语","…, doing …","…, awakening it to flow"],["it takes sth time to do","It takes + 时间 + to do","the time it takes a crest to travel"],["现在完成被动","have/has been + 过去分词","the waves have been generated"]]},"specialRules":[{"rule":"虚拟条件里,if 从句用过去式(be 常用 were),主句用 would/could/might + 原形。","mark":"If … were …, … would …"},{"rule":"cause、get、want、ask 等后接‘宾语 + to do’;to 不能省(区别于 make/let 后省 to)。","mark":"cause sth to do"},{"rule":"美式拼写:meter(米,英式 metre)、center(中心,英式 centre)。本课已按美语写。","mark":"meter / center"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l40',1,NULL,'Waves are the children of the long struggle between the ocean and the atmosphere. Rays from the sun energize the air, awakening it to flow and to move; the wind then carries the message of the sun to the sea, and the sea transmits it onward through waves.','海浪是海洋与大气之间那场漫长搏斗的孩子。太阳的光线为空气注入能量,唤醒它流动、运动;风随后把太阳的讯息带给大海,大海又通过波浪把它传递下去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l40',2,NULL,'These ocean waves are among the most complicated of all natural phenomena. Each one has a crest, the highest point of the wave, and a trough, the lowest; its height is the vertical distance from the trough to the crest, its wave length the horizontal distance between two crests, and its period the time it takes a single crest to travel one wave length.','这些海浪是一切自然现象中最复杂的之一。每一道浪都有一个波峰——浪的最高点,和一个波谷——最低点;它的浪高是从波谷到波峰的垂直距离,浪长是两个相邻波峰之间的水平距离,而周期则是一个波峰走过一个波长所需的时间。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l40',3,NULL,'Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality the wave moves through the water and leaves the water about where it was. If the water was truly moving with the wave, the ocean and everything on it would be racing into the shore, with plainly catastrophic results.','虽然一道海浪给你的印象,是一堵水墙正朝你的方向涌来,实际上浪是穿过水而行的,把水大致留在它原来的地方。假如水真的随浪一起移动,大海连同上面的一切都会冲向海岸,后果显然是灾难性的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l40',4,NULL,'A wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing it toward the advancing wave, up into the wave, forward with it, and then — as the wave leaves the particle behind — back to its starting point again.','一道穿过深水的海浪,使水面上的一个微粒沿着大致圆形的轨道运动:先把它拉向前进中的浪,再送它上到浪里,随浪向前,然后——当浪把这个微粒抛在身后——又回到它出发的那一点。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l40',5,NULL,'The undulating waves of the open sea are generated by three natural causes: the wind, movements or tremors of the earth, and the gravitational pull of the moon and the sun. Once the waves have been generated, gravity is the force that drives them on, in a continual attempt to restore the surface of the sea to a flat and level plain.','外海那些起伏的波浪由三种自然的力量生成:风,大地的运动或震颤,以及月亮和太阳的引力。而一旦波浪已经生成,重力便成了驱使它们前行的力量,不停地试图把海面重新恢复为平坦、齐整的一片。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
