INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l40','subject to','',NULL,'/ˈsʌbdʒekt tuː/','A wave is subject to the same laws as any living thing.','一道浪受制于和任何活物一样的规律。','Prices are subject to change without notice.','价格可能随时变动,恕不另行通知。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l40','pass through','',NULL,'/pæs θruː/','A wave passing through deep water moves the particles.','穿过深水的浪会带动那些微粒。','Light passes through the clear glass.','光穿过透明的玻璃。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l40','in actuality','',NULL,'/ɪn ˌæktʃuˈæləti/','In actuality, the water stays about where it was.','实际上,水大致留在原来的地方。','It seems simple, but in actuality it is hard.','它看似简单,实际上很难。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l40','give the impression of','',NULL,'/ɡɪv ðə ɪmˈpreʃn ʌv/','A wave gives the impression of a moving wall of water.','浪给人一堵水墙在移动的印象。','He gives the impression of being calm.','他给人一种沉着的印象。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp1','choice','{"stem":"\"If the water was moving with the wave, everything on it ___ racing into the shore.\"(与事实相反的虚拟条件,主句用‘助动词+动词’,填该助动词那一形式)","options":["has been","is","will be","would be"],"answer_index":3,"stem_cn":"如果水真随波移动,水上一切都会冲向海岸。","explanation_cn":"与事实相反的虚拟条件,主句用 would + 动词;此处‘会正在冲’用 would be racing。✓ everything would be racing into the shore. ✗ will be(不用于虚拟)/ is / has been:虚拟主句用 would。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp1','choice','{"stem":"\"If a wave carried the water along, the results ___ be catastrophic.\"(虚拟条件主句,填助动词)","options":["have","are","would","will"],"answer_index":2,"stem_cn":"如果波浪把水一起带走,后果将是灾难性的。","explanation_cn":"虚拟条件主句用 would + 动词原形。✓ the results would be catastrophic. ✗ will(不用于虚拟)/ are / have:虚拟主句用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp1','choice','{"stem":"\"If the sea ___ still, there would be no waves at all.\"(与现在事实相反,if 从句里 be 动词用哪个形式)","options":["has been","were","is","will be"],"answer_index":1,"stem_cn":"如果大海静止不动,就根本不会有波浪。","explanation_cn":"与现在事实相反,if 从句中 be 动词各人称都用 were。✓ if the sea were still. ✗ is(陈述)/ will be / has been:虚拟条件从句用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp2','choice','{"stem":"\"An ocean wave causes a particle on the surface ___ move in a circular orbit.\"(cause + 宾语 + 不定式,填不定式前的那个词)","options":["that","for","/","to"],"answer_index":3,"stem_cn":"海浪使水面上的微粒沿圆形轨道运动。","explanation_cn":"cause + 宾语 + 不定式,‘使…做…’;to 不能省。✓ causes a particle to move. ✗ 省略号(不可省 to)/ that / for:cause 后接 to do。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp2','choice','{"stem":"\"The wind causes the sea ___ rise and fall in a steady rhythm.\"(cause + 宾语 + 不定式,填不定式前的那个词)","options":["to","/","so","that"],"answer_index":0,"stem_cn":"风使海面以平稳的节奏起伏。","explanation_cn":"cause + 宾语 + 不定式;填 to。✓ causes the sea to rise and fall. ✗ 省略 / that / so:cause 后接 to do。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp2','choice','{"stem":"\"Sunlight causes the atmosphere ___ flow and move.\"(cause + 宾语 + 不定式,填不定式前的那个词)","options":["that","/","to","for"],"answer_index":2,"stem_cn":"阳光使大气流动起来。","explanation_cn":"cause + 宾语 + 不定式;填 to。✓ causes the atmosphere to flow. ✗ 省略 / that / for:cause 后接 to do。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp3','choice','{"stem":"\"Rays from the sun energize the air, ___ it to flow.\"(现在分词作状语,填‘唤醒’那个动词的-ing形式)","options":["awakening","awaken","awakened","to awaken"],"answer_index":0,"stem_cn":"阳光使空气充满能量,唤醒它流动起来。","explanation_cn":"现在分词作状语,表伴随;填 awaken 的 -ing 形式。✓ energize the air, awakening it to flow. ✗ awakened(过去分词表被动)/ awaken(原形)/ to awaken:伴随状语用现在分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp3','choice','{"stem":"\"Waves move through the water, ___ it about where it was.\"(现在分词作状语,填‘留下’那个动词的-ing形式)","options":["leave","to leave","leaving","left"],"answer_index":2,"stem_cn":"波浪穿水而过,把水留在大致原处。","explanation_cn":"现在分词作状语,表伴随;填 leave 的 -ing 形式。✓ move through the water, leaving it where it was. ✗ left / leave / to leave:伴随状语用现在分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp3','choice','{"stem":"\"The particle rises and falls, ___ back to its starting point.\"(现在分词作状语,填‘回来’那个动词的-ing形式)","options":["coming","came","to come","come"],"answer_index":0,"stem_cn":"微粒起起落落,又回到它的起点。","explanation_cn":"现在分词作状语,表伴随;填 come 的 -ing 形式。✓ rises and falls, coming back to its start. ✗ came / come / to come:伴随状语用现在分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp4','choice','{"stem":"\"A period is the time it ___ a wave crest to travel one wave length.\"(‘做…需要…时间’,填表示‘花费(时间)’那个动词的第三人称单数)","options":["spends","uses","takes","costs"],"answer_index":2,"stem_cn":"周期就是一个波峰走过一个波长所需的时间。","explanation_cn":"‘做…需要…时间’= it takes … to do;主语 it 用第三人称单数 takes。✓ the time it takes a crest to travel one wave length. ✗ spends(主语须是人)/ costs(主语多为物/钱,不接不定式作时间)/ uses:此结构用 take。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp4','choice','{"stem":"\"It ___ the wave several seconds to reach the shore.\"(‘某物做某事需要…时间’,填那个动词的第三人称单数)","options":["takes","spends","costs","makes"],"answer_index":0,"stem_cn":"波浪要好几秒才能到达岸边。","explanation_cn":"it takes sth + 时间 + to do;填 takes。✓ It takes the wave several seconds to reach the shore. ✗ spends / costs / makes:此结构用 take。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp4','choice','{"stem":"\"It took the storm only minutes ___ raise the waves.\"(它花了…时间去做某事,填不定式记号)","options":["/","for","that","to"],"answer_index":3,"stem_cn":"那场风暴只用几分钟就掀起了巨浪。","explanation_cn":"it takes … time + 不定式;填不定式记号 to。✓ It took the storm only minutes to raise the waves. ✗ 省略 / that / for:此结构用 to do。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp5','choice','{"stem":"\"Once waves ___ been generated, gravity drives them toward the shore.\"(现在完成被动语态,填最前面那个助动词)","options":["are","will","have","did"],"answer_index":2,"stem_cn":"波浪一旦形成,重力便驱使它们涌向海岸。","explanation_cn":"现在完成被动 have/has been + 过去分词;主语 waves 复数用 have。✓ Once waves have been generated … ✗ are(一般被动)/ will / did:现在完成被动用 have been done。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp5','choice','{"stem":"\"The message of the sun ___ been transmitted to the sea by the wind.\"(现在完成被动语态,填那个助动词)","options":["did","has","will","is"],"answer_index":1,"stem_cn":"太阳的讯息已由风传给了大海。","explanation_cn":"现在完成被动;主语 message 单数用 has。✓ The message has been transmitted. ✗ is / will / did:现在完成被动用 has been done。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp5','choice','{"stem":"\"The ocean surface ___ been restored to a flat plain after the wave.\"(现在完成被动语态,填那个助动词)","options":["will","is","has","did"],"answer_index":2,"stem_cn":"浪过之后,海面已被重新恢复为平坦的一片。","explanation_cn":"现在完成被动;主语 surface 单数用 has。✓ The ocean surface has been restored. ✗ is / will / did:现在完成被动用 has been done。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp6','choice','{"stem":"\"To give energy or power to something is to ___ it.\"(“使充满能量,激励”用哪个词)","options":["memorize","energize","apologize","organize"],"answer_index":1,"stem_cn":"给某物注入能量或动力。","explanation_cn":"给某物注入能量或动力是 energize(使充满能量、激励)。✓ to give energy to something is to energize it. ✗ organize 组织;✗ memorize 记住;✗ apologize 道歉——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp6','choice','{"stem":"\"The highest point of a wave is its ___.\"(“波峰”用哪个词)","options":["crest","particle","trough","signature"],"answer_index":0,"stem_cn":"波浪的最高点。","explanation_cn":"波浪的最高点是 crest(波峰、顶点)。✓ the highest point of a wave is its crest. ✗ trough 波谷;✗ particle 微粒;✗ signature 签名——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',5,'am4_l40_gp6','choice','{"stem":"\"Causing great and sudden damage or suffering is ___.\"(“灾难性的”用哪个词)","options":["systematic","catastrophic","dramatic","automatic"],"answer_index":1,"stem_cn":"造成巨大而突然的破坏或痛苦的。","explanation_cn":"造成巨大而突然破坏或痛苦的是 catastrophic(灾难性的)。✓ causing great and sudden damage is catastrophic. ✗ systematic 系统的;✗ automatic 自动的;✗ dramatic 戏剧性的——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',6,NULL,'choice','{"stem":"energize 的意思是:","options":["使平静","使疲惫","使充满能量,激励","使困惑"],"answer_index":2,"explanation_cn":"energize = 使充满能量、激励。✓ rays from the sun energize the air."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',6,NULL,'choice','{"stem":"transmit 的意思是:","options":["传送,传递","储存","吸收","阻断"],"answer_index":0,"explanation_cn":"transmit = 传送、传递。✓ the sea transmits it onward."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',6,NULL,'choice','{"stem":"crest 的意思是:","options":["漩涡","波峰,顶点","波谷","水滴"],"answer_index":1,"explanation_cn":"crest = 波峰、顶点。✓ a crest, the highest point of the wave."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',6,NULL,'choice','{"stem":"trough 的意思是:","options":["浪花","山顶","波峰","波谷,低谷"],"answer_index":3,"explanation_cn":"trough = 波谷、低谷。✓ a trough, the lowest point."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',6,NULL,'choice','{"stem":"catastrophic 的意思是:","options":["有益的","微小的","灾难性的","短暂的"],"answer_index":2,"explanation_cn":"catastrophic = 灾难性的。✓ with plainly catastrophic results."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',6,NULL,'choice','{"stem":"phenomena 的意思是:","options":["理论","原因","结果","现象"],"answer_index":3,"explanation_cn":"phenomena = 现象(phenomenon 的复数)。✓ among the most complicated natural phenomena."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',7,NULL,'cloze','{"stem":"第 1 空","context":"If the water was really moving with the wave, everything ___1___ be racing to the shore. A wave causes a particle ___2___ move in a circular orbit. Sunlight energizes the air, ___3___ it into motion. Once waves ___4___ been generated, gravity drives them on.","blank_no":1,"options":["would","will","is","has"],"answer_index":0,"explanation_cn":"与事实相反的虚拟条件,主句用 would + 动词原形。✓ everything would be racing to the shore."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',7,NULL,'cloze','{"stem":"第 2 空","context":"If the water was really moving with the wave, everything ___1___ be racing to the shore. A wave causes a particle ___2___ move in a circular orbit. Sunlight energizes the air, ___3___ it into motion. Once waves ___4___ been generated, gravity drives them on.","blank_no":2,"options":["to","/","that","for"],"answer_index":0,"explanation_cn":"cause + 宾语 + 不定式;填 to。✓ causes a particle to move."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',7,NULL,'cloze','{"stem":"第 3 空","context":"If the water was really moving with the wave, everything ___1___ be racing to the shore. A wave causes a particle ___2___ move in a circular orbit. Sunlight energizes the air, ___3___ it into motion. Once waves ___4___ been generated, gravity drives them on.","blank_no":3,"options":["awakening","awakened","awaken","to awaken"],"answer_index":0,"explanation_cn":"现在分词作状语,表伴随;填 awaken 的 -ing 形式。✓ energizes the air, awakening it into motion."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',7,NULL,'cloze','{"stem":"第 4 空","context":"If the water was really moving with the wave, everything ___1___ be racing to the shore. A wave causes a particle ___2___ move in a circular orbit. Sunlight energizes the air, ___3___ it into motion. Once waves ___4___ been generated, gravity drives them on.","blank_no":4,"options":["have","are","will","did"],"answer_index":0,"explanation_cn":"现在完成被动 have been + 过去分词;主语 waves 复数用 have。✓ Once waves have been generated …"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',8,NULL,'choice','{"stem":"What false impression does an ocean wave give to the observer?","options":["That waves never move at all","That the water is racing to the shore with the wave","That the sea is completely still","That a wall of water is moving toward the shore, though the water itself stays about where it was"],"answer_index":3,"explanation_cn":"录音说:海浪给人的错觉,是一堵水墙朝岸边涌来,而水本身其实大致留在原处。✓ false impression: a moving wall of water."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',8,NULL,'choice','{"stem":"What three natural causes generate the waves of the open sea?","options":["Wind, earth movements or tremors, and the gravitational pull of the moon and sun","Only the moon","Rain, snow and ice","Only the wind"],"answer_index":0,"explanation_cn":"录音说:外海波浪由三种自然力生成——风、大地运动或震颤、月与日的引力。✓ three causes."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',8,NULL,'choice','{"stem":"After waves have been generated, what force drives them on?","options":["The wind alone","The heat of the sun","Gravity, trying to restore the ocean surface to a flat plain","The rotation of the earth"],"answer_index":2,"explanation_cn":"录音说:波浪生成后,是重力驱使它们前行,不断试图把海面恢复为平坦一片。✓ gravity restores flat plain."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',9,NULL,'choice','{"stem":"你想说\"如果水真随波移动,一切都会冲向海岸\"(与事实相反的虚拟条件):","options":["If the water was moving with the wave, everything would be racing to the shore.","If the water moving with the wave, everything would be racing to the shore.","If the water was moving with the wave, everything will be racing to the shore.","If the water is moving with the wave, everything would be racing to the shore."],"answer_index":0,"explanation_cn":"与事实相反的虚拟条件;if 从句用过去式 was moving(不用 is moving)、主句用 would(不用 will)、be 动词不能漏(不写 the water moving)。✓ If … was …, … would … 场合:说“(与事实相反)如果…就会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',9,NULL,'choice','{"stem":"你想说\"海浪使水面上的微粒沿圆形轨道运动\"(cause sb/sth to do):","options":["An ocean wave causes a particle move in a circular orbit.","An ocean wave causes a particle moving in a circular orbit.","An ocean wave causes a particle to move in a circular orbit.","An ocean wave causes to a particle move in a circular orbit."],"answer_index":2,"explanation_cn":"cause + 名词 + 不定式;particle 后接 to move(不省 to、不用 moving)、cause 后不加 to(不写 causes to a particle)。✓ causes a particle to move. 场合:说“使某物做…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',9,NULL,'choice','{"stem":"你想说\"波浪一旦形成,重力便驱使它们涌向海岸\"(现在完成被动):","options":["Once waves has been generated, gravity drives them toward the shore.","Once waves have generated, gravity drives them toward the shore.","Once waves are generating, gravity drives them toward the shore.","Once waves have been generated, gravity drives them toward the shore."],"answer_index":3,"explanation_cn":"现在完成被动 have been + 过去分词;waves 复数用 have(不用 has)、须有 been(不写 have generated)、不用进行 are generating。✓ have been generated. 场合:说“…一旦被…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"energize 的意思是:","options":["使充满能量,激励","使困惑","使平静","使疲惫"],"answer_index":0,"explanation_cn":"energize = 使充满能量、激励。✓ rays from the sun energize the air."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"crest 的意思是:","options":["漩涡","波峰,顶点","波谷","水滴"],"answer_index":1,"explanation_cn":"crest = 波峰、顶点。✓ a crest, the highest point of the wave."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"\"If the water was moving with the wave, everything ___ be racing to the shore.\"(与事实相反的虚拟条件,主句)","options":["is","has","would","will"],"answer_index":2,"stem_cn":"若水随波移动,一切都会冲向海岸。","explanation_cn":"与事实相反的虚拟条件,主句用 would。✓ everything would be racing to the shore. ✗ will / is / has。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"\"An ocean wave causes a particle ___ move in a circular orbit.\"(cause + 宾语 + 不定式)","options":["to","/","for","that"],"answer_index":0,"stem_cn":"海浪使微粒沿圆形轨道运动。","explanation_cn":"cause + 宾语 + 不定式;填 to。✓ causes a particle to move. ✗ 省略 / that / for。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"\"subject to\" 的意思是:","options":["免于…","反对…","优于…","受…支配,须服从…"],"answer_index":3,"explanation_cn":"subject to = 受…支配、须服从…。✓ a wave is subject to the same laws."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"\"in actuality\" 的意思是:","options":["理论上","表面上","实际上,事实上","偶然地"],"answer_index":2,"explanation_cn":"in actuality = 实际上、事实上。✓ in actuality the water stays where it was."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"Why does the water not travel to the shore with an ocean wave?","options":["Because gravity pulls it back to the moon","The wave moves through the water, leaving the water about where it was","Because the water is frozen","Because there is no wind"],"answer_index":1,"passage":"Waves are the children of the long struggle between the ocean and the atmosphere. Rays from the sun energize the air, awakening it to flow and to move; the wind then carries the message of the sun to the sea, and the sea transmits it onward through waves. These ocean waves are among the most complicated of all natural phenomena. Each one has a crest, the highest point of the wave, and a trough, the lowest; its height is the vertical distance from the trough to the crest, its wave length the horizontal distance between two crests, and its period the time it takes a single crest to travel one wave length. Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality the wave moves through the water and leaves the water about where it was. If the water was truly moving with the wave, the ocean and everything on it would be racing into the shore, with plainly catastrophic results. A wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing it toward the advancing wave, up into the wave, forward with it, and then — as the wave leaves the particle behind — back to its starting point again. From birth to death, a wave is subject to the same laws as any other living thing. For a time it takes on a kind of individuality, and then, in the end, it is reabsorbed into the great ocean from which it came. The undulating waves of the open sea are generated by three natural causes: the wind, movements or tremors of the earth, and the gravitational pull of the moon and the sun. Once the waves have been generated, gravity is the force that drives them on, in a continual attempt to restore the surface of the sea to a flat and level plain.","explanation_cn":"课文说:浪是穿水而行的,把水大致留在原处,故水并不随浪冲向海岸。✓ wave moves through, water stays."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"What happens to a wave from birth to death?","options":["It briefly takes on a kind of individuality, then is reabsorbed into the great ocean","It turns into wind","It grows larger forever","It sinks to the sea floor and stays there"],"answer_index":0,"passage":"Waves are the children of the long struggle between the ocean and the atmosphere. Rays from the sun energize the air, awakening it to flow and to move; the wind then carries the message of the sun to the sea, and the sea transmits it onward through waves. These ocean waves are among the most complicated of all natural phenomena. Each one has a crest, the highest point of the wave, and a trough, the lowest; its height is the vertical distance from the trough to the crest, its wave length the horizontal distance between two crests, and its period the time it takes a single crest to travel one wave length. Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality the wave moves through the water and leaves the water about where it was. If the water was truly moving with the wave, the ocean and everything on it would be racing into the shore, with plainly catastrophic results. A wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing it toward the advancing wave, up into the wave, forward with it, and then — as the wave leaves the particle behind — back to its starting point again. From birth to death, a wave is subject to the same laws as any other living thing. For a time it takes on a kind of individuality, and then, in the end, it is reabsorbed into the great ocean from which it came. The undulating waves of the open sea are generated by three natural causes: the wind, movements or tremors of the earth, and the gravitational pull of the moon and the sun. Once the waves have been generated, gravity is the force that drives them on, in a continual attempt to restore the surface of the sea to a flat and level plain.","explanation_cn":"课文说:一道浪有一阵子显出奇异的个性,最终又被重新吸纳进浩瀚的海洋。✓ individuality then reabsorbed."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"What false impression does an ocean wave convey?","options":["That waves never reach the land","That the water races along with the wave","That the sea is always still","That a wall of water is moving toward the shore"],"answer_index":3,"audio":"Waves are the children of the long struggle between the ocean and the atmosphere. Rays from the sun energize the air, awakening it to flow and to move; the wind then carries the message of the sun to the sea, and the sea transmits it onward through waves. These ocean waves are among the most complicated of all natural phenomena. Each one has a crest, the highest point of the wave, and a trough, the lowest; its height is the vertical distance from the trough to the crest, its wave length the horizontal distance between two crests, and its period the time it takes a single crest to travel one wave length. Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality the wave moves through the water and leaves the water about where it was. If the water was truly moving with the wave, the ocean and everything on it would be racing into the shore, with plainly catastrophic results. A wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing it toward the advancing wave, up into the wave, forward with it, and then — as the wave leaves the particle behind — back to its starting point again. From birth to death, a wave is subject to the same laws as any other living thing. For a time it takes on a kind of individuality, and then, in the end, it is reabsorbed into the great ocean from which it came. The undulating waves of the open sea are generated by three natural causes: the wind, movements or tremors of the earth, and the gravitational pull of the moon and the sun. Once the waves have been generated, gravity is the force that drives them on, in a continual attempt to restore the surface of the sea to a flat and level plain.","explanation_cn":"课文说:海浪的错觉,是一堵水墙正朝岸边涌来。✓ false impression of a moving wall."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l40',10,NULL,'choice','{"stem":"Once waves have been generated, what restores the sea to a flat plain?","options":["The sun''s heat","The wind","Gravity","The tides of the moon only"],"answer_index":2,"audio":"Waves are the children of the long struggle between the ocean and the atmosphere. Rays from the sun energize the air, awakening it to flow and to move; the wind then carries the message of the sun to the sea, and the sea transmits it onward through waves. These ocean waves are among the most complicated of all natural phenomena. Each one has a crest, the highest point of the wave, and a trough, the lowest; its height is the vertical distance from the trough to the crest, its wave length the horizontal distance between two crests, and its period the time it takes a single crest to travel one wave length. Although an ocean wave gives the impression of a wall of water moving in your direction, in actuality the wave moves through the water and leaves the water about where it was. If the water was truly moving with the wave, the ocean and everything on it would be racing into the shore, with plainly catastrophic results. A wave passing through deep water causes a particle on the surface to move in a roughly circular orbit, drawing it toward the advancing wave, up into the wave, forward with it, and then — as the wave leaves the particle behind — back to its starting point again. From birth to death, a wave is subject to the same laws as any other living thing. For a time it takes on a kind of individuality, and then, in the end, it is reabsorbed into the great ocean from which it came. The undulating waves of the open sea are generated by three natural causes: the wind, movements or tremors of the earth, and the gravitational pull of the moon and the sun. Once the waves have been generated, gravity is the force that drives them on, in a continual attempt to restore the surface of the sea to a flat and level plain.","explanation_cn":"课文说:波浪生成后,是重力不断试图把海面恢复为平坦一片。✓ gravity restores flat plain."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l41',4,7,41,'Training Elephants','训练大象','consist of + 动名词(由…构成/在于)、be capable of + 名词/动名词(能够…)、be deprived of(被剥夺…)、every time 引导时间从句(每当/一…就)、it is + 形容词 + for sb to do(for sb 作不定式逻辑主语)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 Richard Carrington《Elephants》一段讲驯象两法与人象纽带的说明文,系版权作品——已用 100% 原创行文复述其要点、无引用原句;⚠️净化:原文强硬训练法含‘鞭打/带金属尖头的刺棒/象鼻磨破’等强制细节,已弱化为‘迫使/坚定而耐心的手’并聚焦温和法与情感纽带;题材=动物训练·净化后无害;美语化 behavior/favor;第四册第41课)','训练大象主要有两种方法,我们不妨称之为强硬法与温和法。强硬法只不过是让动物去干活,一小时又一小时地迫使它做人所期望的事。且不论其中的残忍,这也是个愚蠢的办法,因为它造就的是一头满怀怨恨的动物,日后很可能变得危险。温和法在早期需要多得多的耐心,却能造就一头快活、脾气好、愿意提供多年忠诚服务的大象。训练大象的首要之务,是给这头动物指派单独一名驯象人,由他全权负责。大象喜欢只有一个主人,就像狗一样,而且它们能表现出相当程度的个人情感。甚至有这样的故事:一些半驯的幼象,在因某种不可避免的变故被夺走自己的驯养员后,竟拒绝一切食物、忧郁而死。这类极端的说法多半得打个折扣看待,但它们确实点明了一条总的原则:大象与驯象人之间的纽带,是成功的关键。捕捉一头大象来训练,最划算的年龄是十五到二十岁之间,因为那时它差不多已能承担重活,可以立刻开始挣自己的口粮。但这个年龄的动物不易变得顺从,早期必须用一只坚定而耐心的手。仍被绳拴在树上的被捕大象,每当有人靠近,就又蹦又叫,头几天多半会因恐惧而拒食一切。有时会在近旁拴一头驯服的大象,给这头野的壮胆;多数情况下,被捕的大象会渐渐安静下来,开始接受喂食。当同时训练好几头大象时,惯例是把新来的一头安置在两头已训练得相当到位、更为安静的大象的栏位之间。随后就让它完全不受打扰,给足食物和水,好让它吸收新家的气氛,并看到同伴身上没有发生任何令它惊恐的事。当它终于能正常进食时,它自己那温和的训练便可以开始,训练者会耐心地去赢得动物的信任,用一句柔和、抚慰的话语来强化每一点小小的成功。','{"q":"Listen and answer — At what point does the training of a captive wild elephant begin?","options":["When it has settled in and is eating normally in its new home","The moment it is captured","After it has learned to carry heavy loads","Only when it is twenty years old"],"answer_index":0}'::jsonb,'{"title":"consist of doing / be capable of / be deprived of / every time / it is adj for sb to do","intro":"①consist of + 动名词,‘由…构成/在于…’。②be capable of + 名词或动名词,‘能够…’。③be deprived of,‘被剥夺/失去…’。④every time 引导时间从句,‘每当/一…就…’。⑤it is + 形容词 + for sb to do,it 是形式主语,for sb 是不定式的逻辑主语。","table":{"headers":["用法","结构","例子"],"rows":[["consist of doing","consist of + 动名词","consists of setting it to work"],["be capable of","be capable of + 名词/动名词","capable of personal affection"],["be deprived of","be deprived of + 名词","deprived of their trainer"],["every time","every time + 从句","plunges every time a man approaches"],["it is adj for sb to do","It is + 形容词 + for sb + 不定式","It is customary for it to be placed…"]]},"specialRules":[{"rule":"consist of(由…组成)接名词或动名词,不用被动语态;consist in 则表‘在于’。","mark":"consist of doing"},{"rule":"be capable of、be deprived of、be responsible for 等‘形容词/过去分词 + 介词’搭配要整体记。","mark":"capable/deprived of"},{"rule":"美式拼写:behavior(行为,英式 behaviour)、favor(偏爱,英式 favour)。本课已按美语写。","mark":"behavior / favor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l41',1,NULL,'There are two main techniques for training an elephant, which we may call the harsh and the gentle. The harsh technique simply consists of setting the animal to work and forcing it, hour after hour, to do what is expected of it. Apart from the plain cruelty of it, this is a foolish method, for it produces a resentful animal that at a later stage may well become dangerous.','训练大象主要有两种方法,我们不妨称之为强硬法与温和法。强硬法只不过是让动物去干活,一小时又一小时地迫使它做人所期望的事。且不论其中的残忍,这也是个愚蠢的办法,因为它造就的是一头满怀怨恨的动物,日后很可能变得危险。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l41',2,NULL,'The gentle technique asks for far more patience in the early stages, but it produces a cheerful, good-tempered elephant that will give many years of loyal service. The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job. Elephants like to have one master, just as dogs do, and they are capable of a considerable degree of personal affection.','温和法在早期需要多得多的耐心,却能造就一头快活、脾气好、愿意提供多年忠诚服务的大象。训练大象的首要之务,是给这头动物指派单独一名驯象人,由他全权负责。大象喜欢只有一个主人,就像狗一样,而且它们能表现出相当程度的个人情感。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l41',3,NULL,'There are even stories of half-trained calves that have refused all food and pined to death when, by some unavoidable circumstance, they were deprived of their own trainer. Such extreme tales must probably be taken with a grain of salt, but they do underline the general principle that the bond between elephant and mahout is the key to success.','甚至有这样的故事:一些半驯的幼象,在因某种不可避免的变故被夺走自己的驯养员后,竟拒绝一切食物、忧郁而死。这类极端的说法多半得打个折扣看待,但它们确实点明了一条总的原则:大象与驯象人之间的纽带,是成功的关键。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l41',4,NULL,'The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away. But animals of this age do not easily become subservient, and a firm, patient hand must be used in the early stages. The captive elephant, still roped to a tree, plunges and screams every time a person approaches, and for several days it will probably refuse all food through fear.','捕捉一头大象来训练,最划算的年龄是十五到二十岁之间,因为那时它差不多已能承担重活,可以立刻开始挣自己的口粮。但这个年龄的动物不易变得顺从,早期必须用一只坚定而耐心的手。仍被绳拴在树上的被捕大象,每当有人靠近,就又蹦又叫,头几天多半会因恐惧而拒食一切。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l41',5,NULL,'Sometimes a tame elephant is tethered nearby to give the wild one confidence, and in most cases the captive gradually quietens down and begins to accept its food. When several elephants are being trained at one time, it is customary for the new arrival to be placed between the stalls of two calmer captives whose training is already well advanced. When it is at last eating normally, its own gentle training can begin, and the trainer works patiently to win the animal''s trust, reinforcing every small success with a soft and soothing word.','有时会在近旁拴一头驯服的大象,给这头野的壮胆;多数情况下,被捕的大象会渐渐安静下来,开始接受喂食。当同时训练好几头大象时,惯例是把新来的一头安置在两头已训练得相当到位、更为安静的大象的栏位之间。当它终于能正常进食时,它自己那温和的训练便可以开始,训练者会耐心地去赢得动物的信任,用一句柔和、抚慰的话语来强化每一点小小的成功。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
