INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l41','set ... to work','',NULL,'/set tuː wɜːrk/','They set the young elephant to work too soon.','他们过早让小象去干活。','She set the class to work on a project.','她让全班开始做一个项目。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l41','be responsible for','',NULL,'/bi rɪˈspɑːnsəbl fɔːr/','One mahout is entirely responsible for the animal.','一名驯象人对这头动物全权负责。','Who is responsible for this decision?','谁对这个决定负责?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l41','take with a grain of salt','',NULL,'/teɪk wɪð ə ɡreɪn ʌv sɔːlt/','Such extreme tales must be taken with a grain of salt.','这类极端的说法得打个折扣看待。','I take his promises with a grain of salt.','他的承诺我只是姑妄听之。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l41','earn its keep','',NULL,'/ɜːrn ɪts kiːp/','At fifteen the elephant can begin to earn its keep.','到十五岁,大象就能开始挣自己的口粮。','Every animal on the farm must earn its keep.','农场里每只动物都得自食其力。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp1','choice','{"stem":"\"The tough method simply consists ___ setting the animal to work.\"(consist __ doing,‘由…构成/在于…’,填那个介词)","options":["at","in","of","on"],"answer_index":2,"stem_cn":"强硬法只不过是让动物去干活。","explanation_cn":"consist of + 动名词,‘由…构成/在于…’;固定介词 of。✓ consists of setting the animal to work. ✗ in(consist in 义不同)/ on / at:‘由…组成’用 consist of。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp1','choice','{"stem":"\"Successful training consists of ___ a good relationship first.\"(consist of + 动名词,填‘建立’那个动词的动名词)","options":["building","build","built","to build"],"answer_index":0,"stem_cn":"成功的训练在于先建立良好的关系。","explanation_cn":"consist of + 动名词;填 build 的动名词 building。✓ consists of building a good relationship. ✗ build(原形)/ built / to build:of 后用动名词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp1','choice','{"stem":"\"The gentle method consists of ___ patience in the early stages.\"(consist of + 动名词,填‘表现出’那个动词的动名词)","options":["showed","show","to show","showing"],"answer_index":3,"stem_cn":"温和法在于早期表现出耐心。","explanation_cn":"consist of + 动名词;填 show 的动名词 showing。✓ consists of showing patience. ✗ show / showed / to show:of 后用动名词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp2','choice','{"stem":"\"Elephants are capable ___ deep and lasting affection.\"(be capable __,‘能够…’,填那个介词)","options":["for","of","to","in"],"answer_index":1,"stem_cn":"大象能表现出深厚而持久的情感。","explanation_cn":"be capable of,‘能够…’;固定介词 of。✓ capable of deep and lasting affection. ✗ for / to / in:capable 搭配 of。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp2','choice','{"stem":"\"A well-trained elephant is capable ___ many years'' loyal service.\"(be capable __ + 名词,填那个介词)","options":["to","with","for","of"],"answer_index":3,"stem_cn":"训练有素的大象能提供多年忠诚的服务。","explanation_cn":"be capable of + 名词;填 of。✓ capable of many years'' loyal service. ✗ for / to / with:capable 搭配 of。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp2','choice','{"stem":"\"These animals are capable of ___ their master''s voice.\"(be capable of + 动名词,填‘认出’那个动词的动名词)","options":["recognized","recognize","recognizing","to recognize"],"answer_index":2,"stem_cn":"这些动物能认出主人的声音。","explanation_cn":"be capable of + 动名词;填 recognize 的动名词 recognizing。✓ capable of recognizing its master''s voice. ✗ recognize / recognized / to recognize:of 后用动名词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp3','choice','{"stem":"\"Some calves pined to death when they were deprived ___ their own trainer.\"(be deprived __,‘被剥夺…’,填那个介词)","options":["of","from","with","to"],"answer_index":0,"stem_cn":"有些小象被夺走自己的驯养员后,竟忧郁而死。","explanation_cn":"be deprived of,‘被剥夺/失去…’;固定介词 of。✓ deprived of their own trainer. ✗ from / with / to:deprived 搭配 of。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp3','choice','{"stem":"\"A captive must not be deprived ___ food and water for long.\"(be deprived __,填那个介词)","options":["from","with","at","of"],"answer_index":3,"stem_cn":"被捕的大象不可长时间断绝食水。","explanation_cn":"be deprived of;填 of。✓ deprived of food and water. ✗ from / with / at:deprived 搭配 of。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp3','choice','{"stem":"\"No elephant should be ___ of the single master it trusts.\"(‘被剥夺…’这个结构,填‘剥夺’那个动词的过去分词)","options":["deprived","to deprive","deprive","depriving"],"answer_index":0,"stem_cn":"任何大象都不该被夺走它所信赖的唯一主人。","explanation_cn":"‘被剥夺…’= be deprived of;填 deprive 的过去分词 deprived。✓ should not be deprived of its master. ✗ depriving(主动)/ deprive / to deprive:被动用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp4','choice','{"stem":"\"The captive plunges and screams ___ a man approaches.\"(‘每当…就…’,填引导时间从句的连词组)","options":["in case","as if","every time","even though"],"answer_index":2,"stem_cn":"每当有人靠近,被捕的大象就又蹦又叫。","explanation_cn":"‘每当…就…’引导时间从句用 every time。✓ plunges every time a man approaches. ✗ in case 以防 / as if 好像 / even though 即使:‘每当’用 every time。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp4','choice','{"stem":"\"___ the mahout appears, the elephant grows calm.\"(‘每当…’,填时间连词组)","options":["As if","Even though","In case","Every time"],"answer_index":3,"stem_cn":"每当驯象人出现,大象就安静下来。","explanation_cn":"‘每当…’用 Every time。✓ Every time the mahout appears, it grows calm. ✗ In case / As if / Even though:‘每当’用 Every time。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp4','choice','{"stem":"\"The young elephant refuses food ___ it feels afraid.\"(‘每当…’,填时间连词组)","options":["so that","every time","as if","in case"],"answer_index":1,"stem_cn":"每当害怕,小象就拒绝进食。","explanation_cn":"‘每当…’用 every time。✓ refuses food every time it feels afraid. ✗ in case / as if / so that:‘每当’用 every time。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp5','choice','{"stem":"\"It is customary ___ the new arrival to be placed between two calm elephants.\"(it is + 形容词 + __ sb to do,填 sb 前那个介词)","options":["to","of","for","that"],"answer_index":2,"stem_cn":"惯例是把新来的大象安置在两头安静的大象之间。","explanation_cn":"it is + 形容词 + for sb to do;逻辑主语前用 for。✓ It is customary for the new arrival to be placed … ✗ of(用于 nice/kind of sb)/ to / that:此结构用 for。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp5','choice','{"stem":"\"It is necessary ___ a single mahout to take full charge.\"(__ sb to do 结构,填 sb 前那个介词)","options":["with","for","to","of"],"answer_index":1,"stem_cn":"必须由单独一名驯象人全权负责。","explanation_cn":"for sb to do;逻辑主语前用 for。✓ It is necessary for a single mahout to take charge. ✗ of / to / with:此结构用 for。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp5','choice','{"stem":"\"It is important for the trainer ___ win the animal''s trust.\"(it is + 形容词 + for sb + 不定式,填不定式记号)","options":["of","for","that","to"],"answer_index":3,"stem_cn":"训练者赢得动物的信任很重要。","explanation_cn":"it is + 形容词 + for sb + 不定式;填不定式记号 to。✓ It is important for the trainer to win its trust. ✗ for / that / of:逻辑主语后接 to do。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp6','choice','{"stem":"\"To give a task or duty to someone is to ___ it.\"(“分配,指派”用哪个词)","options":["resign","assign","consign","design"],"answer_index":1,"stem_cn":"把任务或职责交给某人。","explanation_cn":"把任务或职责交给某人是 assign(分配、指派)。✓ to give a duty to someone is to assign it. ✗ resign 辞职;✗ design 设计;✗ consign 托运——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp6','choice','{"stem":"\"Feeling bitter and angry at unfair treatment makes one ___.\"(“愤懑的,充满怨恨的”用哪个词)","options":["respectful","resourceful","restful","resentful"],"answer_index":3,"stem_cn":"因不公待遇而感到痛苦愤怒。","explanation_cn":"因不公待遇而痛苦愤怒是 resentful(愤懑的、充满怨恨的)。✓ feeling bitter and angry makes one resentful. ✗ respectful 恭敬的;✗ resourceful 足智多谋的;✗ restful 宁静的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',5,'am4_l41_gp6','choice','{"stem":"\"To make a feeling or belief stronger is to ___ it.\"(“强化,加强”用哪个词)","options":["reproduce","reinforce","remove","replace"],"answer_index":1,"stem_cn":"使某种感受或信念更强烈。","explanation_cn":"使某种感受或信念更强烈是 reinforce(强化、加强)。✓ to make a belief stronger is to reinforce it. ✗ reproduce 复制;✗ replace 取代;✗ remove 移除——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',6,NULL,'choice','{"stem":"technique 的意思是:","options":["技巧,方法","结果","错误","材料"],"answer_index":0,"explanation_cn":"technique = 技巧、方法。✓ two main techniques for training an elephant."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',6,NULL,'choice','{"stem":"resentful 的意思是:","options":["冷静的","愤懑的,充满怨恨的","满意的","感激的"],"answer_index":1,"explanation_cn":"resentful = 愤懑的、充满怨恨的。✓ it produces a resentful animal."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',6,NULL,'choice','{"stem":"assign 的意思是:","options":["取消","推迟","拒绝","分配,指派"],"answer_index":3,"explanation_cn":"assign = 分配、指派。✓ to assign a single mahout."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',6,NULL,'choice','{"stem":"subservient 的意思是:","options":["傲慢的","顺从的,恭顺的","独立的","敌对的"],"answer_index":1,"explanation_cn":"subservient = 顺从的、恭顺的。✓ do not easily become subservient."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',6,NULL,'choice','{"stem":"soothe 的意思是:","options":["惊吓","激怒","抚慰,使平静","欺骗"],"answer_index":2,"explanation_cn":"soothe = 抚慰、使平静。✓ a soft and soothing word."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',6,NULL,'choice','{"stem":"reinforce 的意思是:","options":["取消","忽视","削弱","强化,加强"],"answer_index":3,"explanation_cn":"reinforce = 强化、加强。✓ reinforcing every small success."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',7,NULL,'cloze','{"stem":"第 1 空","context":"The harsh method consists ___1___ setting the animal to work, and it often produces a resentful animal. Elephants are capable ___2___ deep affection. Some calves even pine when deprived ___3___ their trainer. The captive plunges and screams ___4___ a person approaches.","blank_no":1,"options":["of","in","on","at"],"answer_index":0,"explanation_cn":"consist of + 动名词,‘由…构成’;固定介词 of。✓ consists of setting the animal to work."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',7,NULL,'cloze','{"stem":"第 2 空","context":"The harsh method consists ___1___ setting the animal to work, and it often produces a resentful animal. Elephants are capable ___2___ deep affection. Some calves even pine when deprived ___3___ their trainer. The captive plunges and screams ___4___ a person approaches.","blank_no":2,"options":["of","for","to","in"],"answer_index":0,"explanation_cn":"be capable of,‘能够…’;固定介词 of。✓ capable of deep affection."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',7,NULL,'cloze','{"stem":"第 3 空","context":"The harsh method consists ___1___ setting the animal to work, and it often produces a resentful animal. Elephants are capable ___2___ deep affection. Some calves even pine when deprived ___3___ their trainer. The captive plunges and screams ___4___ a person approaches.","blank_no":3,"options":["of","from","with","to"],"answer_index":0,"explanation_cn":"be deprived of,‘被剥夺…’;固定介词 of。✓ deprived of their trainer."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',7,NULL,'cloze','{"stem":"第 4 空","context":"The harsh method consists ___1___ setting the animal to work, and it often produces a resentful animal. Elephants are capable ___2___ deep affection. Some calves even pine when deprived ___3___ their trainer. The captive plunges and screams ___4___ a person approaches.","blank_no":4,"options":["every time","in case","as if","even though"],"answer_index":0,"explanation_cn":"‘每当…就…’引导时间从句用 every time。✓ plunges and screams every time a person approaches."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',8,NULL,'choice','{"stem":"At what point does the training of a captive wild elephant begin?","options":["Only when it is twenty years old","The moment it is captured","After it has learned to carry heavy loads","When it has settled in and is eating normally in its new home"],"answer_index":3,"explanation_cn":"录音说:当被捕的野象安顿下来、能在新家正常进食时,它自己的训练才开始。✓ eating normally, training begins."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',8,NULL,'choice','{"stem":"Why is a single mahout assigned to each elephant?","options":["Because one man is cheaper than several","Because elephants like one master and form a strong personal bond, like dogs","Because mahouts dislike working together","Because the law requires it"],"answer_index":1,"explanation_cn":"录音说:每头象只配一名驯象人,因为象像狗一样喜欢一个主人,并结下强烈的个人情感纽带。✓ one master, personal bond."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',8,NULL,'choice','{"stem":"What is said to be the key to successful elephant training?","options":["The age at which the elephant is captured","The sharpness of the trainer''s stick","The relationship between the elephant and its mahout","The size of the training establishment"],"answer_index":2,"explanation_cn":"录音说:大象与驯象人之间的关系,才是成功训练的关键。✓ elephant–mahout relationship."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',9,NULL,'choice','{"stem":"你想说\"温和法在于早期表现出耐心\"(consist of + 动名词):","options":["The gentle method consists of showing patience in the early stages.","The gentle method consists of show patience in the early stages.","The gentle method consists of showed patience in the early stages.","The gentle method consists showing patience in the early stages."],"answer_index":0,"explanation_cn":"consist of + 动名词;of 后用 showing(不用原形 show、不用 showed)、of 不能漏(不写 consists showing)。✓ consists of showing … 场合:说“(某事)在于/由…构成”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',9,NULL,'choice','{"stem":"你想说\"有些小象被夺走驯养员后竟忧郁而死\"(be deprived of):","options":["Some calves pined to death when they deprived of their trainer.","Some calves pined to death when they were deprived from their trainer.","Some calves pined to death when they were deprived of their trainer.","Some calves pined to death when they were deprive of their trainer."],"answer_index":2,"explanation_cn":"be deprived of;固定介词 of(不用 from)、被动须有 were(不写 they deprived)、过去分词 deprived(不写 deprive)。✓ were deprived of … 场合:说“被剥夺/失去…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',9,NULL,'choice','{"stem":"你想说\"每当有人靠近,被捕的大象就又蹦又叫\"(every time 引导时间从句):","options":["Every time when a person approaches, the captive plunges and screams.","Every time a person approaches, so the captive plunges and screams.","The every time a person approaches, the captive plunges and screams.","Every time a person approaches, the captive plunges and screams."],"answer_index":3,"explanation_cn":"every time 引导时间从句,‘每当…就…’;主句不再加 so(不写 …, so …)、every time 后不加 when(不写 every time when)、句首不加 The。✓ Every time …, … 场合:说“每当…就…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"technique 的意思是:","options":["材料","技巧,方法","结果","错误"],"answer_index":1,"explanation_cn":"technique = 技巧、方法。✓ two main techniques for training an elephant."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"resentful 的意思是:","options":["感激的","冷静的","满意的","愤懑的,充满怨恨的"],"answer_index":3,"explanation_cn":"resentful = 愤懑的、充满怨恨的。✓ it produces a resentful animal."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"\"The gentle method consists ___ showing patience.\"(consist + 介词 + 动名词)","options":["in","at","of","on"],"answer_index":2,"stem_cn":"温和法在于表现出耐心。","explanation_cn":"consist of + 动名词;固定介词 of。✓ consists of showing patience. ✗ in / on / at。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"\"Some calves pined when they were deprived ___ their trainer.\"(be deprived + 介词)","options":["of","to","with","from"],"answer_index":0,"stem_cn":"有些小象被夺走驯养员后憔悴而死。","explanation_cn":"be deprived of,‘被剥夺…’;固定介词 of。✓ deprived of their trainer. ✗ from / with / to。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"\"be responsible for\" 的意思是:","options":["依赖…","害怕…","对…负责","反对…"],"answer_index":2,"explanation_cn":"be responsible for = 对…负责。✓ one mahout is responsible for the animal."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"\"earn its keep\" 的意思是:","options":["保持安静","保住工作","保守秘密","挣够自己的开销,自食其力"],"answer_index":3,"explanation_cn":"earn its keep = 挣够自己的开销、自食其力。✓ can begin to earn its keep."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"Why is the harsh method of training criticized?","options":["It takes far too long","It requires too many trainers","It produces a resentful animal that may become dangerous","It costs too much money"],"answer_index":2,"passage":"There are two main techniques for training an elephant, which we may call the harsh and the gentle. The harsh technique simply consists of setting the animal to work and forcing it, hour after hour, to do what is expected of it. Apart from the plain cruelty of it, this is a foolish method, for it produces a resentful animal that at a later stage may well become dangerous. The gentle technique asks for far more patience in the early stages, but it produces a cheerful, good-tempered elephant that will give many years of loyal service. The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job. Elephants like to have one master, just as dogs do, and they are capable of a considerable degree of personal affection. There are even stories of half-trained calves that have refused all food and pined to death when, by some unavoidable circumstance, they were deprived of their own trainer. Such extreme tales must probably be taken with a grain of salt, but they do underline the general principle that the bond between elephant and mahout is the key to success. The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away. But animals of this age do not easily become subservient, and a firm, patient hand must be used in the early stages. The captive elephant, still roped to a tree, plunges and screams every time a person approaches, and for several days it will probably refuse all food through fear. Sometimes a tame elephant is tethered nearby to give the wild one confidence, and in most cases the captive gradually quietens down and begins to accept its food. When several elephants are being trained at one time, it is customary for the new arrival to be placed between the stalls of two calmer captives whose training is already well advanced. It is then left completely undisturbed, with plenty of food and water, so that it can absorb the atmosphere of its new home and see that nothing alarming is happening to its companions. When it is at last eating normally, its own gentle training can begin, and the trainer works patiently to win the animal''s trust, reinforcing every small success with a soft and soothing word.","explanation_cn":"课文说:强硬法受批评,是因为它造就满怀怨恨、日后可能变得危险的动物。✓ resentful, may turn dangerous."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"What is the most economical age to capture an elephant for training, and why?","options":["Over forty, because it is calmer","At birth, because it is easy to move","Any age, because age makes no difference","Between fifteen and twenty, because it is then almost ready for heavy work"],"answer_index":3,"passage":"There are two main techniques for training an elephant, which we may call the harsh and the gentle. The harsh technique simply consists of setting the animal to work and forcing it, hour after hour, to do what is expected of it. Apart from the plain cruelty of it, this is a foolish method, for it produces a resentful animal that at a later stage may well become dangerous. The gentle technique asks for far more patience in the early stages, but it produces a cheerful, good-tempered elephant that will give many years of loyal service. The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job. Elephants like to have one master, just as dogs do, and they are capable of a considerable degree of personal affection. There are even stories of half-trained calves that have refused all food and pined to death when, by some unavoidable circumstance, they were deprived of their own trainer. Such extreme tales must probably be taken with a grain of salt, but they do underline the general principle that the bond between elephant and mahout is the key to success. The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away. But animals of this age do not easily become subservient, and a firm, patient hand must be used in the early stages. The captive elephant, still roped to a tree, plunges and screams every time a person approaches, and for several days it will probably refuse all food through fear. Sometimes a tame elephant is tethered nearby to give the wild one confidence, and in most cases the captive gradually quietens down and begins to accept its food. When several elephants are being trained at one time, it is customary for the new arrival to be placed between the stalls of two calmer captives whose training is already well advanced. It is then left completely undisturbed, with plenty of food and water, so that it can absorb the atmosphere of its new home and see that nothing alarming is happening to its companions. When it is at last eating normally, its own gentle training can begin, and the trainer works patiently to win the animal''s trust, reinforcing every small success with a soft and soothing word.","explanation_cn":"课文说:最划算的捕捉年龄是十五到二十岁,那时它差不多已能承担重活、立刻挣口粮。✓ 15–20, ready for work."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"How do trainers help a frightened captive settle in at first?","options":["They keep it completely alone in the dark","They never feed it until it obeys","They leave it undisturbed with food and water, sometimes with a tame elephant nearby for confidence","They force it to work at once"],"answer_index":2,"audio":"There are two main techniques for training an elephant, which we may call the harsh and the gentle. The harsh technique simply consists of setting the animal to work and forcing it, hour after hour, to do what is expected of it. Apart from the plain cruelty of it, this is a foolish method, for it produces a resentful animal that at a later stage may well become dangerous. The gentle technique asks for far more patience in the early stages, but it produces a cheerful, good-tempered elephant that will give many years of loyal service. The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job. Elephants like to have one master, just as dogs do, and they are capable of a considerable degree of personal affection. There are even stories of half-trained calves that have refused all food and pined to death when, by some unavoidable circumstance, they were deprived of their own trainer. Such extreme tales must probably be taken with a grain of salt, but they do underline the general principle that the bond between elephant and mahout is the key to success. The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away. But animals of this age do not easily become subservient, and a firm, patient hand must be used in the early stages. The captive elephant, still roped to a tree, plunges and screams every time a person approaches, and for several days it will probably refuse all food through fear. Sometimes a tame elephant is tethered nearby to give the wild one confidence, and in most cases the captive gradually quietens down and begins to accept its food. When several elephants are being trained at one time, it is customary for the new arrival to be placed between the stalls of two calmer captives whose training is already well advanced. It is then left completely undisturbed, with plenty of food and water, so that it can absorb the atmosphere of its new home and see that nothing alarming is happening to its companions. When it is at last eating normally, its own gentle training can begin, and the trainer works patiently to win the animal''s trust, reinforcing every small success with a soft and soothing word.","explanation_cn":"课文说:起初让受惊的被捕象不受打扰、供足食水,有时在旁拴一头驯象为它壮胆。✓ undisturbed, tame nearby."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l41',10,NULL,'choice','{"stem":"According to the passage, how do elephants resemble dogs?","options":["They dislike all human company","They like to have one master and can feel real personal affection","They cannot be trained at all","They enjoy chasing balls"],"answer_index":1,"audio":"There are two main techniques for training an elephant, which we may call the harsh and the gentle. The harsh technique simply consists of setting the animal to work and forcing it, hour after hour, to do what is expected of it. Apart from the plain cruelty of it, this is a foolish method, for it produces a resentful animal that at a later stage may well become dangerous. The gentle technique asks for far more patience in the early stages, but it produces a cheerful, good-tempered elephant that will give many years of loyal service. The first essential in elephant training is to assign to the animal a single mahout who will be entirely responsible for the job. Elephants like to have one master, just as dogs do, and they are capable of a considerable degree of personal affection. There are even stories of half-trained calves that have refused all food and pined to death when, by some unavoidable circumstance, they were deprived of their own trainer. Such extreme tales must probably be taken with a grain of salt, but they do underline the general principle that the bond between elephant and mahout is the key to success. The most economical age to capture an elephant for training is between fifteen and twenty years, for it is then almost ready to undertake heavy work and can begin to earn its keep straight away. But animals of this age do not easily become subservient, and a firm, patient hand must be used in the early stages. The captive elephant, still roped to a tree, plunges and screams every time a person approaches, and for several days it will probably refuse all food through fear. Sometimes a tame elephant is tethered nearby to give the wild one confidence, and in most cases the captive gradually quietens down and begins to accept its food. When several elephants are being trained at one time, it is customary for the new arrival to be placed between the stalls of two calmer captives whose training is already well advanced. It is then left completely undisturbed, with plenty of food and water, so that it can absorb the atmosphere of its new home and see that nothing alarming is happening to its companions. When it is at last eating normally, its own gentle training can begin, and the trainer works patiently to win the animal''s trust, reinforcing every small success with a soft and soothing word.","explanation_cn":"课文说:大象像狗一样喜欢只有一个主人,能产生真切的个人情感。✓ one master, personal affection."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l42',4,7,42,'Recording an Earthquake','记录地震','It was … that 强调句(强调状语)、neither … nor(既不…也不…)、be to do(表‘要/将/注定’)、by + 动名词(通过做…,表方式)、so … that(如此…以致…)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 H.H. Swinnerton《The Earth beneath Us》一段讲地震仪原理的科普文,系版权作品——已用 100% 原创行文复述其原理、无引用原句;题材=地震物理·无害;美语化 program/catalog;第四册第42课)','地震像夜里的窃贼,毫无预警地到来。因此,人们必须发明既不打盹、也不睡觉的仪器。最早的一些装置相当简单。比如有一种,是把粗细、长短不一的小木杆像九柱戏的木柱那样,竖立在一张坚硬的桌子上。当震动传来、摇动桌子时,轻微的震颤只会推倒最不稳的木杆,而剧烈的震颤则把它们全都掀倒。于是这些木杆,借着倒下、以及倒下的方向,替熟睡的科学家记录下了两件事:一次连他都没能惊醒的微弱震动的强度,以及它来自的方向。但若要取得真正重大的进展,就需要精密得多的仪器。所追求的理想,是一种能用笔在纸上记录地震经过时地面运动的装置。我写字时,笔在动而纸不动;只要多加练习,我迟早也能学会让笔不动、纸动着来写字。这听上去像个荒唐的主意,却正是早期地震仪所采用的原理。难处在于:当桌子、笔架和纸一起晃动时,怎样才能写得清楚?关键藏在一个日常观察里。一位站着的乘客,为什么在公交车骤然起步时容易向后倒?因为他的脚随车前移,而他的头一瞬间却还留在原处。把一个重物拴在一根长绳末端,握住绳子让重物几乎触到地面;这时把手来回晃动,你会发现重物只是轻微地动,甚至几乎不动。最早的仪器正是依据这一原理造出来的:悬着的重物和它带的笔保持不动,而纸在笔尖下面来回移动,于是纸的每一点动作都被墨水描了下来。在最早的仪器里,纸绕在一只缓缓转动的圆筒上;当圆筒被轻轻摇动时,笔画出的线便左右扭动。然而这样的图示记录,只反映了运动中水平的那一部分,而实际的运动要复杂得多。现代仪器可以如此安放,使上下、前后、左右三种运动各自被记录在不同的图表上。当仪器距地震中心超过七百英里时,记录会显示三道波以短暂的间隔一道接一道地到来。第一道标志着较快的纵波的到达;第二道是较慢的横波,晚几分钟才到。正是从对这两道——都穿过地球本体而行——的耐心研究中,人们才对地球隐秘的内部了解了如此之多。','{"q":"Listen and answer — What does a pen have to do to record on paper the vibrations generated by an earthquake?","options":["It must stay still while the paper moves beneath it, so its point traces the movement","It must move up and down very fast","It must be pressed hard onto the drum","It must be replaced after every shock"],"answer_index":0}'::jsonb,'{"title":"It was … that 强调句 / neither … nor / be to do / by + 动名词 / so … that","intro":"①It is/was + 被强调部分 + that + 其余:强调状语等成分。②neither … nor …:‘既不…也不…’。③be to do:表‘要/将/注定/职责’(if any advance was to be made)。④by + 动名词:‘通过做…’,表方式。⑤so + 形容词/副词 + that …:‘如此…以致…’。","table":{"headers":["用法","结构","例子"],"rows":[["It was … that 强调句","It was + 状语 + that + …","It was upon this principle that …"],["neither … nor","neither A nor B","neither slumbered nor slept"],["be to do","was/were + to do","if any advance was to be made"],["by + 动名词","by + doing","recorded by falling"],["so … that","so + 形/副 + that …","so placed that all are recorded"]]},"specialRules":[{"rule":"强调句 It is/was … that …:去掉 It is/was 和 that 后,句子仍成立;强调人时 that 可换 who。","mark":"It was … that …"},{"rule":"neither … nor 连接两项,谓语常就近一致;be to do 表按计划、职责或注定要发生的事。","mark":"neither…nor / be to do"},{"rule":"美式拼写:program(程序,英式 programme)、catalog(目录,英式 catalogue)。本课已按美语写。","mark":"program / catalog"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l42',1,NULL,'An earthquake comes like a thief in the night, without warning. It was necessary, therefore, to invent instruments that neither slumbered nor slept. One of the earliest devices consisted of rods of various lengths and thicknesses which stood on end like ninepins on a rigid table.','地震像夜里的窃贼,毫无预警地到来。因此,人们必须发明既不打盹、也不睡觉的仪器。最早的装置之一,是把粗细、长短不一的小木杆像九柱戏的木柱那样,竖立在一张坚硬的桌子上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l42',2,NULL,'When a shock came and shook the table, a gentle tremor toppled only the least stable rods, while a violent one brought them all down. Thus the rods, by falling and by the direction in which they fell, recorded for the sleeping scientist both the strength of a shock too weak to wake him and the direction from which it had come.','当震动传来、摇动桌子时,轻微的震颤只会推倒最不稳的木杆,而剧烈的震颤则把它们全都掀倒。于是这些木杆,借着倒下、以及倒下的方向,替熟睡的科学家记录下了两件事:一次连他都没能惊醒的微弱震动的强度,以及它来自的方向。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l42',3,NULL,'But instruments far more delicate than these were needed if any really serious advance was to be made. The ideal to be aimed at was a device that could record, with a pen on paper, the movements of the ground as the quake passed by. While I write, my pen moves but the paper keeps still; with practice, I could in time learn to write by holding the pen still while the paper moved.','但若要取得真正重大的进展,就需要精密得多的仪器。所追求的理想,是一种能用笔在纸上记录地震经过时地面运动的装置。我写字时,笔在动而纸不动;只要多加练习,我迟早也能学会让笔不动、纸动着来写字。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l42',4,NULL,'The key lay in an everyday observation. Why does a standing passenger tend to fall when a bus starts suddenly? Because his feet move on with the bus, but his head, for an instant, stays still. It was upon this principle that the first instruments were made: the suspended weight and its pen stayed still, while the paper moved from side to side beneath the pen point, so that its every motion was traced in ink.','关键藏在一个日常观察里。一位站着的乘客,为什么在公交车骤然起步时容易向后倒?因为他的脚随车前移,而他的头一瞬间却还留在原处。最早的仪器正是依据这一原理造出来的:悬着的重物和它带的笔保持不动,而纸在笔尖下面来回移动,于是纸的每一点动作都被墨水描了下来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l42',5,NULL,'In the first instruments the paper was wound round a slowly turning drum, and while the drum was gently shaken, the line the pen was drawing wriggled from side to side. When the instrument is more than seven hundred miles from the earthquake''s centre, the record shows three waves arriving one after another. The first marks the faster, longitudinal vibrations; the second, the slower, transverse vibrations. It was from the study of these two that so much was learned about the earth''s hidden interior.','在最早的仪器里,纸绕在一只缓缓转动的圆筒上;当圆筒被轻轻摇动时,笔画出的线便左右扭动。当仪器距地震中心超过七百英里时,记录会显示三道波一道接一道地到来。第一道标志着较快的纵波;第二道是较慢的横波。正是从对这两道波的研究中,人们才对地球隐秘的内部了解了如此之多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l42','earthquake','/ˈɜːrθkweɪk/','n','地震','An earthquake comes like a thief in the night.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l42','slumber','/ˈslʌmbər/','v','睡眠,微睡','instruments that neither slumbered nor slept') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
