INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l42','like a thief in the night','',NULL,'/laɪk ə θiːf ɪn ðə naɪt/','An earthquake comes like a thief in the night.','地震像夜里的窃贼一样到来。','The idea struck me like a thief in the night.','那个念头像夜贼般突然袭上心头。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l42','to and fro','',NULL,'/tuː ənd froʊ/','Now move your hand to and fro.','现在把你的手来回晃动。','The suspended weight swings to and fro.','悬着的重物来回摆动。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l42','one after another','',NULL,'/wʌn ˈæftər əˈnʌðər/','Three waves arrive one after another.','三道波一道接一道地到来。','The guests left one after another.','客人们一个接一个地离开了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l42','keep still','',NULL,'/kiːp stɪl/','My pen moves but the paper keeps still.','我的笔在动,而纸保持不动。','Please keep still while I take the photo.','我拍照时请你别动。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp1','choice','{"stem":"\"It was upon this principle ___ the first seismometers were made.\"(强调句 It was … 后接的那个连接词)","options":["what","that","which","when"],"answer_index":1,"stem_cn":"正是依据这一原理,最早的地震仪被制造出来。","explanation_cn":"It was … that 强调句;被强调的是状语 upon this principle,连接词用 that。✓ It was upon this principle that … ✗ which(强调状语不用 which)/ what / when:强调句连接词用 that。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp1','choice','{"stem":"\"It was from these two waves ___ scientists learned about the earth''s interior.\"(强调句 It was … 后接的那个连接词)","options":["which","where","what","that"],"answer_index":3,"stem_cn":"正是从这两种波中,科学家了解了地球内部。","explanation_cn":"It was … that 强调句;强调状语 from these two waves,用 that。✓ It was from these two waves that … ✗ which / what / where:强调句用 that。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp1','choice','{"stem":"\"It ___ in the dead of night that the earthquake struck the sleeping city.\"(强调句,填 be 动词的过去式)","options":["has","was","is","were"],"answer_index":1,"stem_cn":"正是在深夜,地震袭击了沉睡的城市。","explanation_cn":"It was … that 强调句;主句时态用过去 was。✓ It was in the dead of night that … ✗ is(现在)/ were / has:此处强调句用 was。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp2','choice','{"stem":"\"The instrument must be one that neither slumbers ___ sleeps.\"(‘既不…也不…’,填第二个连词)","options":["but","or","nor","and"],"answer_index":2,"stem_cn":"这仪器必须既不打盹也不睡觉。","explanation_cn":"neither … nor …,‘既不…也不…’;第二个连词用 nor。✓ neither slumbers nor sleeps. ✗ or(用于 either…or)/ and / but:与 neither 呼应用 nor。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp2','choice','{"stem":"\"___ the table nor the paper stays perfectly still during a quake.\"(‘既不…也不…’,填第一个连词)","options":["Both","Not","Either","Neither"],"answer_index":3,"stem_cn":"地震时桌子和纸都不会完全静止。","explanation_cn":"neither … nor …;第一个连词用 Neither。✓ Neither the table nor the paper stays still. ✗ Either(配 or)/ Both / Not:‘既不…也不’首词用 Neither。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp2','choice','{"stem":"\"A good record shows neither too little ___ too much movement.\"(‘既不…也不…’,填第二个连词)","options":["nor","or","so","and"],"answer_index":0,"stem_cn":"好的记录显示的运动既不太少也不太多。","explanation_cn":"neither … nor …;第二个连词用 nor。✓ neither too little nor too much. ✗ or / and / so:与 neither 呼应用 nor。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp3','choice','{"stem":"\"If any serious advance ___ to be made, finer instruments were needed.\"(be to do 表‘要/将’,填 be 动词过去式)","options":["is","does","was","has"],"answer_index":2,"stem_cn":"若要取得真正重大的进展,就需要更精密的仪器。","explanation_cn":"be to do 表‘要/将/注定’;此处过去用 was。✓ if any serious advance was to be made. ✗ is(时态不符)/ has / does:be to do 用 was to do。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp3','choice','{"stem":"\"The ideal ___ be aimed at was a pen that wrote by itself.\"(不定式被动作定语,填该不定式最前面的记号)","options":["for","to","/","that"],"answer_index":1,"stem_cn":"所追求的理想,是一支能自己书写的笔。","explanation_cn":"不定式被动作定语 to be aimed at;填不定式记号 to。✓ The ideal to be aimed at … ✗ 省略(不可省 to)/ that / for:不定式作定语用 to。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp3','choice','{"stem":"\"The scientists knew the great wave ___ to arrive last of all.\"(be to do 表‘注定/将’,填 be 动词过去式)","options":["has","did","was","is"],"answer_index":2,"stem_cn":"科学家知道那道巨波注定最后才到。","explanation_cn":"be to do 表‘注定/将’;过去用 was。✓ the great wave was to arrive last. ✗ is / has / did:be to do 用 was to do。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp4','choice','{"stem":"\"The rods, ___ falling, recorded the strength and direction of the shock.\"(‘通过做…’表方式,填那个介词)","options":["with","for","in","by"],"answer_index":3,"stem_cn":"那些木杆通过倒下,记录了震动的强度和方向。","explanation_cn":"by + 动名词表方式,‘通过做…’;填介词 by。✓ the rods, by falling, recorded … ✗ with / in / for:表方式用 by doing。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp4','choice','{"stem":"\"One could learn to write by ___ the pen still while the paper moved.\"(by + 动名词,填‘保持’那个动词的动名词)","options":["holding","hold","held","to hold"],"answer_index":0,"stem_cn":"人可以通过让笔不动、纸移动来学写字。","explanation_cn":"by + 动名词;填 hold 的动名词 holding。✓ learn to write by holding the pen still. ✗ hold(原形)/ held / to hold:by 后用动名词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp4','choice','{"stem":"\"The seismometer records the quake by ___ the paper move under a still pen.\"(by + 动名词,填‘让’那个动词的动名词)","options":["let","to let","letting","lets"],"answer_index":2,"stem_cn":"地震仪通过让纸在静止的笔下移动来记录地震。","explanation_cn":"by + 动名词;填 let 的动名词 letting。✓ records the quake by letting the paper move. ✗ let / to let / lets:by 后用动名词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp5','choice','{"stem":"\"The instruments can be ___ placed that all three elements are recorded.\"(‘如此…以致…’结构,填第一个词)","options":["too","so","such","very"],"answer_index":1,"stem_cn":"仪器可以如此安放,以致三种成分都被记录下来。","explanation_cn":"so + 过去分词/副词 + that,‘如此…以致…’;填 so。✓ so placed that all three are recorded. ✗ such(接名词短语)/ very / too:‘如此…以致’用 so。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp5','choice','{"stem":"\"The shock was ___ gentle that only the loosest rods fell.\"(‘如此…以致…’,填第一个词)","options":["so","very","too","such"],"answer_index":0,"stem_cn":"那次震动如此轻微,以致只有最松的木杆倒下。","explanation_cn":"so + 形容词 + that,‘如此…以致…’;填 so。✓ so gentle that only the loosest rods fell. ✗ such / very / too:so + 形容词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp5','choice','{"stem":"\"The pen moved ___ little that the line was almost straight.\"(‘如此…以致…’,填第一个词)","options":["such","very","so","too"],"answer_index":2,"stem_cn":"笔动得如此之小,以致画出的线几乎是直的。","explanation_cn":"so + little + that;填 so。✓ so little that the line was almost straight. ✗ such / very / too:so + 副词/形容词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp6','choice','{"stem":"\"A sudden violent shaking of the ground is an ___.\"(“地震”用哪个词)","options":["earthquake","avalanche","hurricane","eruption"],"answer_index":0,"stem_cn":"地面突然的剧烈晃动。","explanation_cn":"地面突然的剧烈晃动是 earthquake(地震)。✓ a sudden violent shaking of the ground is an earthquake. ✗ avalanche 雪崩;✗ eruption 喷发;✗ hurricane 飓风——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp6','choice','{"stem":"\"Something stiff and not able to bend is ___.\"(“坚硬的,僵直的”用哪个词)","options":["fragile","rigid","smooth","hollow"],"answer_index":1,"stem_cn":"僵硬、不能弯曲的。","explanation_cn":"僵硬、不能弯曲的是 rigid(坚硬的、僵直的)。✓ something stiff and unable to bend is rigid. ✗ fragile 易碎的;✗ hollow 空心的;✗ smooth 光滑的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',5,'am4_l42_gp6','choice','{"stem":"\"To twist and turn the body with small quick movements is to ___.\"(“扭动,蠕动”用哪个词)","options":["scatter","tremble","wriggle","stumble"],"answer_index":2,"stem_cn":"身体以细小快速的动作扭来扭去。","explanation_cn":"身体以细小快速的动作扭来扭去是 wriggle(扭动、蠕动)。✓ to twist and turn with small quick movements is to wriggle. ✗ stumble 绊倒;✗ tremble 发抖;✗ scatter 散开——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',6,NULL,'choice','{"stem":"earthquake 的意思是:","options":["火山爆发","飓风","地震","洪水"],"answer_index":2,"explanation_cn":"earthquake = 地震。✓ An earthquake comes like a thief in the night."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',6,NULL,'choice','{"stem":"slumber 的意思是:","options":["睡眠,微睡","奔跑","苏醒","劳作"],"answer_index":0,"explanation_cn":"slumber = 睡眠、微睡。✓ instruments that neither slumbered nor slept."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',6,NULL,'choice','{"stem":"rigid 的意思是:","options":["易碎的","柔软的","光滑的","坚硬的,僵直的"],"answer_index":3,"explanation_cn":"rigid = 坚硬的、僵直的。✓ stood on end on a rigid table."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',6,NULL,'choice','{"stem":"delicate 的意思是:","options":["精密的,精细的","笨拙的","粗糙的","沉重的"],"answer_index":0,"explanation_cn":"delicate = 精密的、精细的。✓ instruments far more delicate than these."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',6,NULL,'choice','{"stem":"wriggle 的意思是:","options":["静止","坠落","扭动,蠕动","漂浮"],"answer_index":2,"explanation_cn":"wriggle = 扭动、蠕动。✓ the line the pen was drawing wriggled from side to side."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',6,NULL,'choice','{"stem":"legibly 的意思是:","options":["字迹清晰地","大声地","潦草地","迅速地"],"answer_index":0,"explanation_cn":"legibly = 字迹清晰地。✓ how is it possible to write legibly?"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',7,NULL,'cloze','{"stem":"第 1 空","context":"The device must neither slumber ___1___ sleep. If any advance ___2___ to be made, finer tools were needed. The rods, ___3___ falling, showed the shock''s strength. The pen moved ___4___ little that the line stayed almost straight.","blank_no":1,"options":["nor","or","and","but"],"answer_index":0,"explanation_cn":"neither … nor …,‘既不…也不…’;第二个连词用 nor。✓ neither slumber nor sleep."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',7,NULL,'cloze','{"stem":"第 2 空","context":"The device must neither slumber ___1___ sleep. If any advance ___2___ to be made, finer tools were needed. The rods, ___3___ falling, showed the shock''s strength. The pen moved ___4___ little that the line stayed almost straight.","blank_no":2,"options":["was","is","has","does"],"answer_index":0,"explanation_cn":"be to do 表‘要/将’;过去用 was。✓ if any advance was to be made."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',7,NULL,'cloze','{"stem":"第 3 空","context":"The device must neither slumber ___1___ sleep. If any advance ___2___ to be made, finer tools were needed. The rods, ___3___ falling, showed the shock''s strength. The pen moved ___4___ little that the line stayed almost straight.","blank_no":3,"options":["by","with","in","for"],"answer_index":0,"explanation_cn":"by + 动名词表方式;填 by。✓ the rods, by falling, showed the shock''s strength."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',7,NULL,'cloze','{"stem":"第 4 空","context":"The device must neither slumber ___1___ sleep. If any advance ___2___ to be made, finer tools were needed. The rods, ___3___ falling, showed the shock''s strength. The pen moved ___4___ little that the line stayed almost straight.","blank_no":4,"options":["so","such","very","too"],"answer_index":0,"explanation_cn":"so + 副词 + that,‘如此…以致…’;填 so。✓ The pen moved so little that the line stayed almost straight."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',8,NULL,'choice','{"stem":"What does a pen have to do to record an earthquake''s vibrations on paper?","options":["It must be pressed hard onto the drum","It must stay still while the paper moves beneath it, so its point traces the movement","It must move up and down very fast","It must be replaced after every shock"],"answer_index":1,"explanation_cn":"录音说:笔(连同悬着的重物)须保持不动,让纸在下方移动,笔尖便把运动描下来。✓ pen still, paper moves."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',8,NULL,'choice','{"stem":"Why does a heavy weight on a long string stay almost still when the hand moves it sideways?","options":["Because of its inertia, much as a standing passenger''s head stays still when a bus starts","Because it is too light to move","Because the string is elastic","Because the ground absorbs the motion"],"answer_index":0,"explanation_cn":"录音说:因惯性,重物几乎不动,正如公交起步时站着乘客的头会短暂滞留原处。✓ inertia, like passenger''s head."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',8,NULL,'choice','{"stem":"When the instrument is far (over 700 miles) from the earthquake''s centre, what does the record show?","options":["A single steady line","Only the largest shock","Three waves arriving one after another at short intervals","Nothing at all"],"answer_index":2,"explanation_cn":"录音说:仪器距震中超过七百英里时,记录会显示三道波以短暂间隔先后到来。✓ three waves in sequence."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',9,NULL,'choice','{"stem":"你想说\"正是依据这一原理,最早的地震仪被造出来\"(It was … that 强调句):","options":["It was upon this principle when the first seismometers were made.","It was upon this principle the first seismometers were made.","It was upon this principle which the first seismometers were made.","It was upon this principle that the first seismometers were made."],"answer_index":3,"explanation_cn":"It was … that 强调句;被强调的状语后用 that(不用 which/when)、that 不能漏(不写 It was upon this principle the first…)。✓ It was … that … 场合:强调某一成分,‘正是…’。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',9,NULL,'choice','{"stem":"你想说\"这仪器必须既不打盹也不睡觉\"(neither … nor):","options":["The instrument must neither slumbers nor sleeps.","The instrument must neither slumber nor sleep.","The instrument must not neither slumber nor sleep.","The instrument must neither slumber or sleep."],"answer_index":1,"explanation_cn":"neither … nor;第二项用 nor(不用 or)、must 后接原形 slumber(不用 slumbers)、句中已有否定不再加 not(不写 must not neither)。✓ neither slumber nor sleep. 场合:说“既不…也不…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',9,NULL,'choice','{"stem":"你想说\"那些木杆通过倒下记录了震动的强度\"(by + 动名词):","options":["The rods recorded the shock''s strength by fall.","The rods recorded the shock''s strength by to fall.","The rods recorded the shock''s strength by falling.","The rods recorded the shock''s strength by fell."],"answer_index":2,"explanation_cn":"by + 动名词表方式;by 后用 falling(不用原形 fall、过去式 fell、也不用 to fall)。✓ by falling. 场合:说“通过做…(方式)”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"earthquake 的意思是:","options":["洪水","飓风","火山爆发","地震"],"answer_index":3,"explanation_cn":"earthquake = 地震。✓ An earthquake comes like a thief in the night."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"rigid 的意思是:","options":["坚硬的,僵直的","易碎的","柔软的","光滑的"],"answer_index":0,"explanation_cn":"rigid = 坚硬的、僵直的。✓ stood on end on a rigid table."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"\"It was upon this principle ___ the first seismometers were made.\"(It was … 后接连接词的强调句)","options":["which","what","when","that"],"answer_index":3,"stem_cn":"正是依据这一原理造出最早的地震仪。","explanation_cn":"It was … that 强调句;强调状语用 that。✓ It was upon this principle that … ✗ which / what / when。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"\"The device must neither slumber ___ sleep.\"(‘既不…也不…’结构)","options":["or","and","nor","but"],"answer_index":2,"stem_cn":"这装置既不打盹也不睡觉。","explanation_cn":"neither … nor …;第二个连词用 nor。✓ neither slumber nor sleep. ✗ or / and / but。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"\"to and fro\" 的意思是:","options":["上上下下地","缓慢地","静止不动地","来回地,往复地"],"answer_index":3,"explanation_cn":"to and fro = 来回地、往复地。✓ move your hand to and fro."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"\"one after another\" 的意思是:","options":["同时地","偶尔地","一个接一个地","从不地"],"answer_index":2,"explanation_cn":"one after another = 一个接一个地。✓ three waves arrive one after another."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"Why were the simple falling-rod devices not good enough for serious study?","options":["They could not be built","They needed electricity","They were too expensive","They only showed the rough strength and direction, not the detailed movement of the ground"],"answer_index":3,"passage":"An earthquake comes like a thief in the night, without warning. It was necessary, therefore, to invent instruments that neither slumbered nor slept. Some of the earliest devices were quite simple. One, for instance, consisted of rods of various lengths and thicknesses which stood on end like ninepins on a rigid table. When a shock came and shook the table, a gentle tremor toppled only the least stable rods, while a violent one brought them all down. Thus the rods, by falling and by the direction in which they fell, recorded for the sleeping scientist both the strength of a shock too weak to wake him and the direction from which it had come. But instruments far more delicate than these were needed if any really serious advance was to be made. The ideal to be aimed at was a device that could record, with a pen on paper, the movements of the ground as the quake passed by. While I write, my pen moves but the paper keeps still; with practice, I could in time learn to write by holding the pen still while the paper moved. That sounds a silly idea, yet it was precisely the principle adopted in the early seismometers. The difficulty is this: when table, penholder and paper are all shaking together, how is it possible to write legibly? The key lay in an everyday observation. Why does a standing passenger tend to fall when a bus starts suddenly? Because his feet move on with the bus, but his head, for an instant, stays still. Tie a heavy weight to a long string and hold it so that the weight nearly touches the ground; now move your hand to and fro, and it will be found that the weight moves only slightly, or not at all. It was upon this principle that the first instruments were made: the suspended weight and its pen stayed still, while the paper moved from side to side beneath the pen point, so that its every motion was traced in ink. In the first instruments the paper was wound round a slowly turning drum, and while the drum was gently shaken, the line the pen was drawing wriggled from side to side. Such a graphic record, however, shows only the horizontal part of the movement, which is in fact far more complicated. Modern instruments can be so placed that the up-and-down, to-and-fro and side-to-side motions are each set down in separate graphs. When the instrument is more than seven hundred miles from the earthquake''s centre, the record shows three waves arriving one after another at short intervals. The first marks the arrival of the faster, longitudinal vibrations; the second, the slower, transverse vibrations, which arrive several minutes later. It was from the patient study of these two, both of which travel through the body of the earth, that so much was learned about the planet''s hidden interior.","explanation_cn":"课文说:落杆式简易装置只能显示大致的强度与方向,记不下地面细致的运动,故不够用于深入研究。✓ only rough strength/direction."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"What is the difference between the first two waves that reach a distant instrument?","options":["Neither wave travels through the earth","The first are longitudinal and faster; the second are transverse and slower, arriving minutes later","They are exactly the same","The first are slower than the second"],"answer_index":1,"passage":"An earthquake comes like a thief in the night, without warning. It was necessary, therefore, to invent instruments that neither slumbered nor slept. Some of the earliest devices were quite simple. One, for instance, consisted of rods of various lengths and thicknesses which stood on end like ninepins on a rigid table. When a shock came and shook the table, a gentle tremor toppled only the least stable rods, while a violent one brought them all down. Thus the rods, by falling and by the direction in which they fell, recorded for the sleeping scientist both the strength of a shock too weak to wake him and the direction from which it had come. But instruments far more delicate than these were needed if any really serious advance was to be made. The ideal to be aimed at was a device that could record, with a pen on paper, the movements of the ground as the quake passed by. While I write, my pen moves but the paper keeps still; with practice, I could in time learn to write by holding the pen still while the paper moved. That sounds a silly idea, yet it was precisely the principle adopted in the early seismometers. The difficulty is this: when table, penholder and paper are all shaking together, how is it possible to write legibly? The key lay in an everyday observation. Why does a standing passenger tend to fall when a bus starts suddenly? Because his feet move on with the bus, but his head, for an instant, stays still. Tie a heavy weight to a long string and hold it so that the weight nearly touches the ground; now move your hand to and fro, and it will be found that the weight moves only slightly, or not at all. It was upon this principle that the first instruments were made: the suspended weight and its pen stayed still, while the paper moved from side to side beneath the pen point, so that its every motion was traced in ink. In the first instruments the paper was wound round a slowly turning drum, and while the drum was gently shaken, the line the pen was drawing wriggled from side to side. Such a graphic record, however, shows only the horizontal part of the movement, which is in fact far more complicated. Modern instruments can be so placed that the up-and-down, to-and-fro and side-to-side motions are each set down in separate graphs. When the instrument is more than seven hundred miles from the earthquake''s centre, the record shows three waves arriving one after another at short intervals. The first marks the arrival of the faster, longitudinal vibrations; the second, the slower, transverse vibrations, which arrive several minutes later. It was from the patient study of these two, both of which travel through the body of the earth, that so much was learned about the planet''s hidden interior.","explanation_cn":"课文说:先到的是较快的纵波,随后是较慢的横波,晚几分钟才到。✓ longitudinal fast, transverse slow."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"How does a seismometer manage to write while everything is shaking?","options":["The scientist holds the pen by hand","The paper is kept perfectly still","It uses no pen at all","A suspended weight and pen stay still while the moving paper records the motion"],"answer_index":3,"audio":"An earthquake comes like a thief in the night, without warning. It was necessary, therefore, to invent instruments that neither slumbered nor slept. Some of the earliest devices were quite simple. One, for instance, consisted of rods of various lengths and thicknesses which stood on end like ninepins on a rigid table. When a shock came and shook the table, a gentle tremor toppled only the least stable rods, while a violent one brought them all down. Thus the rods, by falling and by the direction in which they fell, recorded for the sleeping scientist both the strength of a shock too weak to wake him and the direction from which it had come. But instruments far more delicate than these were needed if any really serious advance was to be made. The ideal to be aimed at was a device that could record, with a pen on paper, the movements of the ground as the quake passed by. While I write, my pen moves but the paper keeps still; with practice, I could in time learn to write by holding the pen still while the paper moved. That sounds a silly idea, yet it was precisely the principle adopted in the early seismometers. The difficulty is this: when table, penholder and paper are all shaking together, how is it possible to write legibly? The key lay in an everyday observation. Why does a standing passenger tend to fall when a bus starts suddenly? Because his feet move on with the bus, but his head, for an instant, stays still. Tie a heavy weight to a long string and hold it so that the weight nearly touches the ground; now move your hand to and fro, and it will be found that the weight moves only slightly, or not at all. It was upon this principle that the first instruments were made: the suspended weight and its pen stayed still, while the paper moved from side to side beneath the pen point, so that its every motion was traced in ink. In the first instruments the paper was wound round a slowly turning drum, and while the drum was gently shaken, the line the pen was drawing wriggled from side to side. Such a graphic record, however, shows only the horizontal part of the movement, which is in fact far more complicated. Modern instruments can be so placed that the up-and-down, to-and-fro and side-to-side motions are each set down in separate graphs. When the instrument is more than seven hundred miles from the earthquake''s centre, the record shows three waves arriving one after another at short intervals. The first marks the arrival of the faster, longitudinal vibrations; the second, the slower, transverse vibrations, which arrive several minutes later. It was from the patient study of these two, both of which travel through the body of the earth, that so much was learned about the planet''s hidden interior.","explanation_cn":"课文说:靠悬着的重物与笔保持不动、让移动的纸来记录,才能在晃动中写下记录。✓ suspended weight still, paper moves."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l42',10,NULL,'choice','{"stem":"What was learned from studying the two waves that travel through the earth?","options":["Much about the interior of the earth","Nothing useful","The color of the rocks","The exact time of the next quake"],"answer_index":0,"audio":"An earthquake comes like a thief in the night, without warning. It was necessary, therefore, to invent instruments that neither slumbered nor slept. Some of the earliest devices were quite simple. One, for instance, consisted of rods of various lengths and thicknesses which stood on end like ninepins on a rigid table. When a shock came and shook the table, a gentle tremor toppled only the least stable rods, while a violent one brought them all down. Thus the rods, by falling and by the direction in which they fell, recorded for the sleeping scientist both the strength of a shock too weak to wake him and the direction from which it had come. But instruments far more delicate than these were needed if any really serious advance was to be made. The ideal to be aimed at was a device that could record, with a pen on paper, the movements of the ground as the quake passed by. While I write, my pen moves but the paper keeps still; with practice, I could in time learn to write by holding the pen still while the paper moved. That sounds a silly idea, yet it was precisely the principle adopted in the early seismometers. The difficulty is this: when table, penholder and paper are all shaking together, how is it possible to write legibly? The key lay in an everyday observation. Why does a standing passenger tend to fall when a bus starts suddenly? Because his feet move on with the bus, but his head, for an instant, stays still. Tie a heavy weight to a long string and hold it so that the weight nearly touches the ground; now move your hand to and fro, and it will be found that the weight moves only slightly, or not at all. It was upon this principle that the first instruments were made: the suspended weight and its pen stayed still, while the paper moved from side to side beneath the pen point, so that its every motion was traced in ink. In the first instruments the paper was wound round a slowly turning drum, and while the drum was gently shaken, the line the pen was drawing wriggled from side to side. Such a graphic record, however, shows only the horizontal part of the movement, which is in fact far more complicated. Modern instruments can be so placed that the up-and-down, to-and-fro and side-to-side motions are each set down in separate graphs. When the instrument is more than seven hundred miles from the earthquake''s centre, the record shows three waves arriving one after another at short intervals. The first marks the arrival of the faster, longitudinal vibrations; the second, the slower, transverse vibrations, which arrive several minutes later. It was from the patient study of these two, both of which travel through the body of the earth, that so much was learned about the planet''s hidden interior.","explanation_cn":"课文说:正是从对穿过地球本体的两道波的研究中,人们了解了地球内部的许多情况。✓ learned about earth''s interior."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
